Medic.internal.newLifeQuestFixTranslations = {
    ["Coldharbour Voidmother^f"] = "madre del Vacío de Puerto Gélido^f",
    ["Coldharbour Void-Shade^m"] = "sombra del Vacío de Puerto Gélido^f",
    ["Coldharbour Void-Shade^f"] = "sombra del Vacío de Puerto Gélido^f",
    ["Worm Cult Nightblade^m"] = "hoja nocturna del Culto del Gusano^m",
    ["Worm Cult Nightblade^f"] = "hoja nocturna del Culto del Gusano^f",
    ["Stirk Fellowship Soldier^m"] = "soldado de la Hermandad de Stirk^m",
    ["Stirk Fellowship Mage^f"] = "maga de la Hermandad de Stirk^f",
    ["Voidmother^n"] = "madre del Vacío^f",
    ["Nightblade^m"] = "hoja nocturna^m",
    ["Darkbinder Nightblade^f"] = "vinculadora oscura hoja nocturna^f",
    ["Dead Argonian"] = "argoniano muerto^m",
    ["Statue^m"] = "estatua^f",
    ["Statue^f"] = "estatua^f",
    ["Applies to Mages' Fury, Endless Fury, and Mages' Wrath. Select in Skills menu."] = "Se aplica a furia del mago, furia interminable y cólera del mago. Se selecciona en el menú de habilidades.",
    ["Applies to Dark Exchange, Dark Conversion, and Dark Deal. Select in Skills menu."] = "Se aplica a intercambio oscuro, conversión oscura y tratado oscuro. Se selecciona en el menú de habilidades.",
    ["Applies to Siphoning Strikes, Leeching Strikes, and Siphoning Attacks. Select in Skills menu."] = "Se aplica a golpes succionadores, golpes drenadores y ataques succionadores. Se selecciona en el menú de habilidades.",
    ["Applies to Strife, Funnel Health, and Swallow Soul. Select in Skills menu."] = "Se aplica a conflicto, canalización de salud y engullir alma. Se selecciona en el menú de habilidades.",
    ["Magma Armor, Azure Blue"] = "Armadura magmática: azul cerúleo",
    ["Applies to Magma Armor, Corrosive Armor, and Magma Shell. Select in Skills menu."] = "Se aplica a armadura magmática, armadura corrosiva y caparazón magmático. Se selecciona en el menú de habilidades.",
    ["Molten Weapons, Azure Blue"] = "Armas fundidas: azul cerúleo",
    ["Applies to Molten Weapons, Igneous Weapons, and Molten Armaments. Select in Skills menu."] = "Se aplica a armas fundidas, armas incandescentes y armamento fundido. Se selecciona en el menú de habilidades.",
    ["Applies to Arrow Spray, Acid Spray, and Bombard. Select in Skills menu."] = "Se aplica a ráfaga de flechas, ráfaga ácida y bombardear. Se selecciona en el menú de habilidades.",
    ["Applies to Twin Slashes, Blood Craze, and Rending Slashes. Select in Skills menu."] = "Se aplica a hojas gemelas, manía sangrienta y cuchillada desgarradora. Se selecciona en el menú de habilidades.",
    ["Crate Topper, Moons Over Orsinium"] = "Caja, Superior, Lunas sobre Orsinium",
    ["Applies to Healing Seed, Budding Seeds, and Corrupting Pollen. Select in Skills menu."] = "Se aplica a semilla sanadora, semilla floreciente y polen corruptor. Se selecciona en el menú de habilidades.",
    ["Applies to Cleansing Ritual, Extended Ritual, and Ritual of Retribution. Select in Skills menu."] = "Se aplica a ritual purificador, ritual pertinaz y ritual de retribución. Se selecciona en el menú de habilidades.",
    ["Applies to Grim Focus, Merciless Resolve, and Relentless Focus. Select in Skills menu."] = "Se aplica a enfoque siniestro, determinación despiadada y enfoque implacable. Se selecciona en el menú de habilidades.",
    ["Applies to Frost Cloak, Expansive Frost Cloak, and Ice Fortress. Select in Skills menu."] = "Se aplica a manto de escarcha, gran escarcha oculta y fortaleza de hielo. Se selecciona en el menú de habilidades.",
    ["Applies to Fatecarver, Exhausting Fatecarver, and Pragmatic Fatecarver. Select in Skills menu."] = "Se aplica a forjador del destino, forjador del destino agotador y forjador del destino pragmático. Se selecciona en el menú de habilidades.",
    ["Applies to Snipe, Focused Aim, and Lethal Arrow. Select in Skills menu."] = "Se aplica a disparo preciso, puntería concentrada y flecha letal. Se selecciona en el menú de habilidades.",
    ["Applies to Radiant Destruction, Radiant Glory, and Radiant Oppression. Select in Skills menu."] = "Se aplica a destrucción radiante, gloria radiante y opresión radiante. Se selecciona en el menú de habilidades.",
    ["Applies to Puncturing Strikes, Biting Jabs, and Puncturing Sweep. Select in Skills menu."] = "Se aplica a golpes perforantes, punzada mordaz y barrido punzante. Se selecciona en el menú de habilidades.",
    ["Applies to Bone Armor, Beckoning Armor, and Summoner's Armor. Select in Skills menu."] = "Se aplica a armadura de hueso, armadura de atracción y armadura de invocador. Se selecciona en el menú de habilidades.",
    ["Applies to Render Flesh, Blood Sacrifice, and Resistant Flesh. Select in Skills menu."] = "Se aplica a sanación de carne, sacrificio de sangre y carne resistente. Se selecciona en el menú de habilidades.",
    ["Applies to Abyssal Impact, Cephaliarch's Flail, and Tentacular Dread. Select in Skills menu."] = "Se aplica a impacto abisal, flagelo del Cefaliarca y pavor tentacular. Se selecciona en el menú de habilidades.",
    ["Applies to Runespite Ward, Impervious Runeward, and Spiteward of the Lucid Mind. Select in Skills menu."] = "Se aplica a custodia de rencor rúnico, protección rúnica impenetrable y custodia de rencor de la mente lúcida. Se selecciona en el menú de habilidades.",
    ["Applies to Soul Trap, Consuming Trap, and Soul-Splitting Trap. Select in Skills menu."] = "Se aplica a trampa de alma, trampa consumidora y trampa divisora de almas. Se selecciona en el menú de habilidades.",
    ["A small clay statuette in the shape of a bat, painted with red polish.\n\nThe first of three components required to create the Roseblood Bat."] = "Esta estatuilla con forma de murciélago está hecha de arcilla y pintada con esmalte rojo.\n\nEs el primero de los tres componentes necesarios para el murciélago de sangre rósea.",
    ["Petals that fall from Sanguine's prized roses are not known to wilt, and are always slightly damp with blood.\n\nThe second of three components required to create the Roseblood Bat."] = "Los pétalos que caen de las preciadas rosas de Sanguine no se marchitan y siempre están ligeramente empapados de sangre.\n\nEs el segundo de los tres componentes necesarios para crear el murciélago de sangre rósea.",
    ["A deadly-sharp rose thorn from one of the myriad rosebushes that grow in Sanguine's eternal paradise. Watch your finger!\n\nThe last of three components required to create the Roseblood Bat."] = "Una espina de rosa mortalmente afilada que pertenece a uno de los muchos rosales que crecen en el paraíso eterno de Sanguine. ¡Cuidado con los dedos!\n\nEs el último de los tres componentes necesarios para crear el murciélago de sangre rósea.",
    ["In the halls of the Daedra, their crude mockeries of Tamrielic traditions extend to the courtesies of courtly dancing as well.\n\nA component required for the Roseblood Wings Recall customized action."] = "En los salones daédricos, las groseras burlas de las tradiciones tamriélicas se extienden también a los bailes cortesanos.\n\nEs un componente necesario para la acción personalizada retirada de alas de sangre rósea.",
    ["Darkly beautiful and ringed with bloody thorns, this fashionable accoutrement lures in dance partners while also pricking those who get too close.\n\nA component required for the Roseblood Wings Recall customized action."] = "Este elegante accesorio rodeado de espinas sangrientas tiene una belleza oscura. Atrae a los compañeros de baile a la vez que pincha a quienes se acercan demasiado.\n\nEs un componente necesario para la acción personalizada retirada de alas de sangre rósea.",
    ["Victims of this deadly poison are found with reddened lips; the mark of one last dalliance with forbidden romance.\n\nA component required for the Roseblood Wings Recall customized action."] = "Las víctimas de este veneno letal presentan los labios enrojecidos: la marca del último coqueteo con un romance prohibido.\n\nEs un componente necesario para la acción personalizada retirada de alas de sangre rósea.",
    ["Wardrobe,Costume,Wardrobe,Disguise,Covering,Clothes,Gear,Wear,Worn,Apparel"] = "Armario,Indumentaria,Armario,Disfraz,Revestimiento,Ropa,Equipamiento,Vestir,Ponerse,Vestimenta",
    ["Skill Styles,Skill Style,Skills,Combat,Ability,Abilities,Class, Nightblade,Grim Focus,red ,Relentless Focus, Merciless Resolve"] = "Estilos de habilidad,Estilo de habilidad,Habilidades,Combate,Habilidad,Clase,Hoja nocturna,Enfoque siniestro,Rojo,Enfoque implacable,Determinación despiadada",
    ["This situation is more dire than we feared, five-claw. By the way, did you know Darien has no stealth? His fancy armor makes more noise than an Alfiq at bath time! But this one digresses ….\n\nRaz scouted ahead and could barely believe his eyes!"] = "Esta situación es más grave de lo que nos temíamos, cinco garras. Por cierto, ¿sabías que Darien no es nada sigiloso? ¡Su pomposa armadura hace más ruido que un alfiq cuando se baña! Pero este khajiita se está yendo por las ramas...\n\n¡Mientras reconocía el terreno, Raz casi no daba crédito a lo que veían sus ojos!",
    ["Go on with Jeetra. These death-dancers seem to be quite capable! I'm not sure I totally trust the name, though.\n\nAnd don't worry about me. I'll be fine. Just need to clear my head. And … thanks for earlier. Gave me a lot to think about."] = "Ve con Jeetra. Los Bailarines de la Muerte parecen muy capaces, aunque no sé si debo confiar en ellos.\n\nY no te preocupes por mí. Estaré bien. Solo necesito aclarar mis ideas. Y... gracias por lo de antes. Me has dado mucho que pensar.",
    ["Don't worry about me. I've got this. It will take time for all these doubts and wounds to heal, but I'm with you.\n\nLet's focus on finding Vanus and stopping Mannimarco's ritual. That's more than enough for now."] = "No te preocupes por mí; me las apañaré. Estas dudas y estas heridas tardarán tiempo en curarse, pero estoy contigo.\n\nCentrémonos en encontrar a Vano y detener el ritual de Mannimarco. Por el momento, nos basta y nos sobra con eso.",
    ["I have to ask—was it fun being a giant statue and stepping on cultists? Because it looked like fun from where I was standing.\n\nAnyway, now that we're here, what's next?"] = "No puedo quedarme con las ganas de preguntar: ¿te lo has pasado bien controlando una estatua gigante y pisoteando sectarios? Desde donde yo estaba, parecía divertido.\n\nEn fin, ahora que estamos aquí, ¿qué hacemos?",
    ["What a waste, and all because a lector got greedy. We can rebuild the lodge, but the lives lost … those are gone forever.\n\nStill, it would have been worse if you hadn't shown up. Thanks."] = "Qué desperdicio. Y todo por la codicia de una lectora. La logia podemos reconstruirla, pero las vidas perdidas... no tienen remedio.\n\nAun así, habría sido mucho peor si no hubieses aparecido. Gracias.",
    ["Latanwen took a fire bolt meant for me. If I can't get her out of here, I'll never forgive myself.\n\nBut who are you, stranger? You don't look like a cultist, and you're certainly not part of the college. What are you doing here?"] = "Latanwen recibió un proyectil de fuego que iba dirigido a mí. Si no logro sacarla de aquí, jamás me lo perdonaré.\n\n¿Y tú quién eres, <<player{forastero/forastera}>>? No tienes pinta de <<player{sectario/sectaria}>> y, desde luego, no eres miembro del colegio. ¿Qué estás haciendo aquí?",
    ["May the Ancient Darkness guide your travels, friend. Perhaps I will see you again some dark night. I jest, I jest. I am a morning person.\n\nFeel free to examine my work. The ancient words of the death-dancers are fascinating!"] = "Que la Oscuridad Ancestral te guíe en tus viajes, <<player{amigo/amiga}>>. Quizá vuelva a verte en alguna noche oscura. Estoy de broma. Soy muy mañanero.\n\nExamina mi trabajo todo lo que quieras. ¡Las antiguas palabras de los Bailarines de la Muerte son fascinantes!",
    ["Go get those components for the siege weapon, long-strider.\n\nOr do what Argie says. Suraj isn't your captain. Figure it out yourself! I'm trying to catch some fish. Someone's got to make sure this crew gets fed."] = "Ve a por los componentes para el arma de asedio, zancas largas.\n\nO haz lo que dice Argie. Suraj no es tu capitán. ¡Decide tú! Yo estoy intentando pescar algo. Alguien tiene que alimentar a la tripulación.",
    ["Captain ordered me to stay here and protect the surviving crew.\n\nI would rather be out there doing what you're doing, but orders are orders."] = "La capitana me ha ordenado que me quede aquí y proteja a los miembros supervivientes de la tripulación.\n\nPreferiría salir y hacer lo que haces tú, pero las órdenes son órdenes.",
    ["Don't mind Kauldin. Lector Fenworine's betrayal stung him like an angry netch. And after I was wounded and another apprentice fell, he's been extremely cautious.\n\nBut if you aren't with the Worm Cult, who are you?"] = "No hagas caso a Kauldin. La traición de la lectora Fenworine le ha dolido más que el picotazo de un netch cabreado. Además, después de que me hiriesen y de que perdiéramos a otro aprendiz, anda con pies de plomo.\n\nPero, si no formas parte del Culto del Gusano, ¿quién eres?",
    ["Suraj said he wished we met you before all this. Thinks things would have been different for all of us.\n\nMaybe so. But I've never been one to look back in such a way. Makes my neck hurt."] = "Suraj dice que ojalá te hubiésemos conocido antes de todo esto. Cree que las cosas habrían sido diferentes.\n\nEs posible, pero no me gusta mirar atrás. Me da dolor de cuello.",
    ["Fine job rousing those mutineers. Desa got here just before you. Quite the spitfire, isn't she? So long as she doesn't eat any of the others, or make a habit of mutiny, she'll make a fine addition to the crew.\n\nWell, are you ready?"] = "Qué bien has levantado los ánimos de los amotinados. Desa llegó justo antes que tú. Menuda fiera, ¿eh? Mientras no le dé por comerse a nadie ni le entre la costumbre de amotinarse, será una buena incorporación.\n\nBueno, ¿estás <<player{listo/lista}>>?",
    ["Suraj, you've met already. Argenta … requires a bit more patience. Which is why I asked you to speak to her first.\n\nGot no soul, but she's still got a good heart."] = "Ya conoces a Suraj. Argenta... requiere un poco más de paciencia. Por eso te he pedido que hablases con ella primero.\n\nCarece de alma, pero tiene buen corazón aun así.",
    ["I will aid you if I can, but this fight belongs to you and Darien. The rest of us cannot touch Mannimarco without the Light of Meridia to strengthen our blows."] = "Os ayudaré si está en mi mano, pero Darien y tú sois quienes debéis encargaros de este combate. El resto no podremos ni rozar a Mannimarco sin una luz de Meridia que refuerce nuestros ataques.",
    ["Those blighting cultists and their Daedra took my sister, Lienyl. We were so close to getting away! She wanted to start a new life outside of Coldharbour.\n\nInstead, we just landed in another nightmare."] = "Esos malditos sectarios y sus daedra se llevaron a Lienyl, mi hermana. ¡Estábamos a punto de escaparnos! Ella quería empezar una nueva vida fuera de Puerto Gélido.\n\nY solo hemos conseguido aterrizar en otra pesadilla.",
    ["With all the Daedra, I did not expect to find Tindensea is still here. Perhaps she can help us find the old manuscripts Elder Tso-Nassa spoke of. I would hate to have to search through all these shelves without some guidance."] = "Con todos esos daedra, no esperaba hallar a Tindensea aquí. Tal vez pueda ayudarnos a encontrar los antiguos manuscritos de los que hablaba el anciano Tso-Nassa. No me gustaría tener que registrar todas las estanterías.",
    ["If you're done talking Darien out of his dark mood, I'm eager to hear your report. Jeetra explained about Vanus's note in the mine, but what happened at the soul flayer harvest sites? Skordo and Raz said you destroyed them, but not much else."] = "Si ya has conseguido que Darien se anime, estoy deseando escuchar tu informe. Jeetra nos ha explicado lo de la nota de Vano que estaba en la mina, pero ¿qué ha ocurrido en los lugares de cosecha de los desolladores de almas? Skordo y Raz solo me han dicho que los has destruido.",
    ["Captain One-Eye said you mean to give a speech. Didn't have those back at the Caterwaul. Curious what you have to say."] = "La capitana Ojo Único nos ha contado que quieres pronunciar un discurso. En el Alarido, no hacían estas cosas. Tengo curiosidad por lo que vas a decir.",
    ["That's all I have to give to you! At least let me finish the job before I head back to Sunport and turn myself in. I do have a reputation to uphold."] = "¡Esto es todo lo que puedo darte! Al menos, deja que termine el trabajo antes de volver a Puerto Soleado para entregarme. Tengo una reputación que mantener.",
    ["You get one warning, stranger. I bite. And if you stick around too long, Captain Velehk Sain will take you prisoner and make a meal out of your soul.\n\nNow, get lost before I decide to eat you first."] = "Solo lo diré una vez, <<player{forastero/forastera}>>: muerdo. Y si te quedas por aquí más de la cuenta, el capitán Velehk Sain te apresará y se merendará tu alma.\n\nAhora piérdete antes de que decida usarte de aperitivo.",
    ["That observer is on high alert. Someone must have seen you on your way here and raised the alarm.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "El observador está en alerta máxima. Debe de haberte visto alguien cuando venías para acá y habrá dado la alarma.\n\nYo solo quiero salir de aquí. Si hubiera sabido que el capitán Sain trataba a su tripulación igual de bien que a sus prisioneros, habría preferido ser prisionera.",
    ["Seems like that observer has no idea you're here. You'd lose that advantage if one of us goes with you.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Parece que el observador no tiene ni idea de que estás aquí. Perderías esa ventaja si alguno de nosotros te acompaña.\n\nYo solo quiero salir de aquí. Si hubiera sabido que el capitán Sain trataba a su tripulación igual de bien que a sus prisioneros, habría preferido ser prisionera.",
    ["I am astonished. Ghadaz hasn't performed that well in years. I should start writing letters. People need to see this play."] = "No me lo puedo creer. Hacía años que Ghadaz no actuaba tan bien. Debería empezar a escribir cartas. La gente tiene que ver esta obra.",
    ["Let's leave this horrible place of torment and blood so Terinvel and I can calm down. We can talk back at my campsite."] = "Salgamos de este antro de tormento y sangre para que Terinvel y yo podamos calmarnos. Volveremos a hablar en mi campamento.",
    ["I was enjoying this batch, but as it says in the Tenets of the Black Worm, there's more victims where those came from.\n\nDark Adept Vairisse's rounds usually take her to the other side of that door about this time. You shouldn't keep her waiting."] = "Estaba disfrutando con esta remesa, pero como dicen los Preceptos del Gusano Negro, se pueden sacar más víctimas del mismo lugar.\n\nLa adepta oscura Vairisse suele llegar al otro lado de esa puerta hacia esta hora cuando hace su ronda. No deberías hacerla esperar.",
    ["Traveler! Do not attack Sharadak! This one has captured the vile illusionist, Milie Reynaud, after chasing her across land and sea.\n\nShe is a very dangerous prisoner. If Sharadak is not careful, he may fall prey to another one of her vile tricks!"] = "¡<<player{Viajero/Viajera}>>, no ataques a Sharadak! Este khajiita ha capturado a Milie Reynaud, la vil ilusionista, tras perseguirla por tierra y por mar.\n\nEs una prisionera muy peligrosa. ¡Si Sharadak no tiene cuidado, podría caer presa de otro de sus trucos infames!",
    ["Traveler! Sharadak seeks a bounty for the vile illusionist, Milie Reynaud. She is a master of disguise. This one has chased her across land and sea.\n\nIf this one is not careful, he may fall prey to another one of her devious tricks."] = "¡<<player{Viajero/Viajera}>>! Sharadak espera recibir una recompensa por Milie Reynaud, la vil ilusionista. Es una maestra del disfraz. Este khajiita la ha perseguido por tierra y mar.\n\nSi Sharadak no tiene cuidado, podría caer presa de otro de sus trucos taimados.",
    ["You're not from in the Hall. I would recognize you. Which means you broke in somehow. Maybe through the rumored breaches in the walls?\n\nDon't fear that I'll hurt you, mortal. I just want to find a way out. I can't survive in this place."] = "No eres del salón; si no ya, te conocería. Y eso significa que has entrado de alguna forma, ¿tal vez por las grietas en los muros que se rumorea que hay?\n\nNo temas, no te haré daño, mortal. Solo quiero encontrar una salida. No sobreviviré en este lugar.",
    ["Of all the times for that silly hound to try to be a hero.\n\nNever realized how much I actually care about him."] = "De todas las veces que ese mastín tonto podría hacerse el héroe...\n\nNo era consciente de lo mucho que me importa.",
    ["Traveler! You are not with the Worm Cult, are you? I beg a moment of your time. I need someone to deliver a message to Healer Namreras at the Central Siege Camp.\n\nI need you to tell her that her husband, Tesamoril is … dead."] = "¡<<player{Viajero/Viajera}>>! No eres del Culto del Gusano, ¿verdad? Te ruego que me dediques un poco de tu tiempo. Necesito que alguien vaya al campamento de asedio central y le entregue un mensaje a la sanadora Namreras.\n\nQuiero que le digas que su marido, Tesamoril..., ha muerto.",
    ["Dark Adept Vairisse is a stern commander who does not like to be kept waiting. Which is why we should probably have been faster extracting those souls."] = "La adepta oscura Vairisse es una comandante severa. No le gusta que la hagan esperar. Por eso mismo, seguramente tendríamos que haber extraído esas almas más rápido.",
    ["Is it me or has Skordo gotten worse at holding his liquor?\n\nAnd you! Sit, sit. This has been a long time coming. I've promised you more drinks than I can count. Not sure I can afford to make good on all of them, but let's give it a try!"] = "¿Es cosa mía, o Skordo ha perdido aguante con el alcohol?\n\n¡Y tú! Siéntate, venga. Esto llevaba mucho tiempo pendiente. Te he prometido tantos tragos que he perdido la cuenta. No sé si podré pagarlos todos, pero ¡habrá que intentarlo!",
    ["I must return to the mainland and report all we've uncovered here. Just one more task to add to my already overburdened schedule.\n\nSolstice has been … eventful. I'd welcome a little peace, but peace rarely lingers for those such as us, doesn't it?"] = "Tengo que regresar al continente e informar acerca de todo lo que hemos descubierto. Otra tarea con la que engrosar mi ya desbordada agenda.\n\nSolsticio ha sido... un torbellino de acontecimientos. Agradecería un poco de paz, aunque, para la gente como nosotros, la paz rara vez se prolonga demasiado, ¿no es así?",
    ["Oh, thank you so much! I would have been heartbroken if they didn't get something for New Life. Now, allow me to offer you my gratitude. I hope this helps you on your journeys ahead.\n\nReturn soon and we'll make another meal to offer for New Life!"] = "¡Ay, muchísimas gracias! Se me habría roto el corazón si no hubiesen recibido nada por la Nueva Vida. Ahora, permíteme agradecértelo. Espero que esto te ayude en los viajes venideros.\n\n¡Vuelve pronto y prepararemos otra comida para entregarla como ofrenda por la Nueva Vida!",
    ["Talk to Lanullin"] = "Habla con Lanullin",
    ["I prepared the offering and delivered it to the elder."] = "He preparado la ofrenda y se la he entregado a la persona anciana.",
    ["Then Tibarr proclaims this New Life a success! Allow this one to reward you for your noble efforts. It's the least Tibarr can do for enduring his silly festivity.\n\nAnd Tibarr promises more if you brave his Dragon's lair again!"] = "Entonces, ¡Tibarr declara que esta Nueva Vida ha sido todo un éxito! Deja que este khajiita recompense tus nobles esfuerzos. Es lo menos que puede hacer después de que hayas soportado su disparatado festejo.\n\n¡Y Tibarr promete más si osas adentrarte de nuevo en la guarida del dragón!",
    ["Talk to Tibarr"] = "Habla con Tibarr",
    ["I gave the Dragon's coin to Yarg."] = "Le he entregado a Yarg la moneda del dragón.",
    ["Not bad, traveler. Seeking help is usually a last resort for me, but perhaps I've been too hasty to try to accomplish everything by myself.\n\nThere's still more New Life to celebrate, so feel free to swing by the next time you wander this way."] = "No está nada mal, <<player{viajero/viajera}>>. Normalmente, solo pido ayuda cuando no me queda más remedio, pero quizá me haya apresurado demasiado al intentar hacerlo todo por mi cuenta.\n\nLa celebración de la Nueva Vida aún no ha terminado, así que no dudes en pasarte a saludar la próxima vez que vengas por aquí.",
    ["Talk to Yesei"] = "Habla con Yesei",
    ["Yes, I cornered your Dakoi, and he gave me this fish for you."] = "Sí, he acorralado a tu Dakoi y me ha dado este pez para ti.",
    ["Ah, just like my kin. Take this, along with Mudman's blessing. And you're welcome to return for more.\n\nThe Mudman must thrive through the entire New Life season. And, like all of life, it needs care."] = "Ah, igual que mi familia. Toma esto junto con la bendición del Hombre de Barro. Puedes volver a por más si quieres.\n\nEl Hombre de Barro debe aguantar todos los días de la Nueva Vida y, como todo ser vivo, necesita cuidados.",
    ["Talk to Dailonda"] = "Habla con Dailonda",
    ["You mentioned a reward?"] = "¿Has mencionado una recompensa?",
    ["Oh, you remember that, do you. Well, what the tusk, it's New Life! You earned the boon and more, and you finally gave me some true competition.\n\nCome back for another swing! Surely there's more Oblivion boulders where that one came from!"] = "Ah, te acuerdas de eso, ¿eh? Bueno, ¡qué colmillos! ¡Estamos en la Nueva Vida! Te has ganado la bendición y algo más. Y por fin me has planteado un desafío de verdad.\n\n¡Vuelve cuando quieras para hacer otro intento! ¡Seguro que hay más peñascos de Oblivion cerca de donde estaba ese!",
    ["Talk to Mahagog"] = "Habla con Mahagog",
    ["You mentioned you were going to throw in something extra, I believe."] = "Me parece que dijiste que <<player{el ganador/la ganadora}>> se llevaría algún extra.",
    ["As long as a piece of the All-Maker resides in Garth, his mood will always hang like a sharp blade over New Life. \n\nI'll continue to do my best to keep him entertained, but should you return I may call upon you again for assistance. Happy New Life!"] = "Mientras Garth tenga una parte del Creador en su interior, su humor siempre será como una espada afilada pendiendo sobre la Nueva Vida.\n\nSeguiré haciendo todo lo posible para mantenerlo entretenido, pero quizá vuelva a pedirte ayuda si regresas. ¡Feliz Nueva Vida!",
    ["Talk to Baldan"] = "Habla con Baldan",
    ["You think?"] = "¿Tú crees?",
    ["Indeed. However, centuries of resentment rests beneath these sands. Return if you can to help Yokuda's waters flow here. Another also approaches who may need your help, too.\n\nBefore I take my leave, here. From the Kogo-Hi."] = "Desde luego. Sin embargo, siglos de resentimiento yacen bajo estas arenas. Regresa si puedes para ayudar a que las aguas de Yokuda fluyan aquí. También se acerca otra persona que podría necesitar tu ayuda.\n\nAntes de que me retire, toma. De parte de los kogo-hi.",
    ["Talk to Hassavir"] = "Habla con Hassavir",
    ["The ritual is complete then?"] = "Entonces, ¿el ritual está completo?",
    ["No … but it's like the winds guiding me carried thoughtful eyes, watching my every step. Perhaps it was the heat.\n\nBut I find every ritual helps me understand my own path. And I hope you'll join me again."] = "No..., pero era como si los vientos que me guiaban tuvieran ojos atentos que observaban cada uno de mis pasos. Quizá fuera el calor.\n\nPero parece que cada ritual me ayuda a entender mejor mi propio camino. Y espero que vuelvas a participar conmigo.",
    ["Talk to Jahesi"] = "Habla con Jahesi",
    ["Did you see someone on your journey?"] = "¿Has visto a alguien en tu viaje?",
    ["I regret that it has come to this. A fast moving vampiric change means that Terinvel is a danger to everyone. I must deal with it, as a friend should. \n\nI'm grateful for your steady support and calm demeanor through this. Here's payment as promised."] = "Lamento que haya llegado a esto. Una transformación rápida en vampiro implica que Terinvel es un peligro para todo el mundo. Debo ocuparme de esto, como haría una buena amiga.\n\nMuchas gracias por tu apoyo y por haber mantenido la calma en todo momento. Aquí tienes el pago que te prometí.",
    ["Why does the dark adept put up with that prince?"] = "¿Por qué la adepta oscura aguanta a ese príncipe?",
    ["I do not know which warmth I cherish most. That of the sun's light, the burning coals of our nests, or that of my partner who no longer sleeps beside me. May they rest in stone and memory."] = "No sé qué calor tengo en más estima: el del sol, el de las brasas de nuestros nidos o el de mi pareja, que ya no duerme a mi lado y que ojalá descanse en la piedra y la memoria.",
    ["First, I'll kill you. Then I'll see the end of Captain One-Eye."] = "Primero, te mataré a ti. Luego, iré a por la capitana Ojo Único.",
    ["The Voidmother will soon return! Then nothing can stop us!"] = "¡La madre del Vacío regresará pronto! Entonces, ¡nada nos detendrá!",
    ["The Voidmother's power surges! Do not falter now!"] = "¡El poder de la madre del Vacío se intensifica! ¡No vaciléis ahora!",
    ["The gateway trembles and the Voidmother comes!"] = "¡El portal se estremece ante la llegada de la madre del Vacío!",
    ["The Spriggan's going to be ferrying some well-paying passengers off Solstice. I recognize them from back home, but they haven't recognized me yet.\n\nStrange seeing Gahz and Oorbesh be so civil. And I'll be keeping an eye on their … friend."] = "El Spriggan sacará de Solsticio a unas personas que pagan bien por su pasaje. Son de mi tierra; ya nos conocíamos, pero aún no se han dado cuenta.\n\nSe me hace raro ver a Gahz y a Oorbesh comportarse con tanto civismo. Y no perderé de vista a su... amigo.",
    ["When activated, plays the lively music box composition \"Grave-Stake Gambol.\""] = "Al activarse, suena la vivaz composición musical «Retozo de la estaca sepulcral».",
    ["Music Box, Grave-Stake Gambol"] = "caja de música, «Retozo de la estaca sepulcral»^f",
    ["Achievement Furnishings: Solstice"] = "mobiliario de logros: Solsticio Oriental^m",
    ["This small, well-stitched satchel contains a handful of Trade Bars."] = "Este pequeño morral bien cosido contiene un puñado de barras de comercio.",
    ["Trade Bar Satchel"] = "Burjaca de barras de comercio",
    ["Grants an Outfit Style Collectible. Once used, the Outfit Style is available to all characters on your account. Outfit Styles can be used at an Outfit Station to customize your appearance."] = "Otorga un estilo de atuendo coleccionable. Cuando se utilice, el estilo de atuendo estará disponible para todos los personajes de tu cuenta. Los estilos de atuendo se pueden utilizar en el taller de atuendos para personalizar tu apariencia.",
    ["Bound Style Page: Nokvroz's Greatsword Replica"] = "página de estilo vinculada: Réplica del mandoble de Nokvroz",
    ["Ashbound Hall"] = "Salón Cinéreo^m",
    ["Boss Room"] = "sala del jefe^f",
    ["Generic Stagger Enemy"] = "tambaleo de enemigo genérico^m",
    ["Amulet Area"] = "zona del amuleto^f",
    ["Void Traversal"] = "travesía del Vacío^f",
    ["Void Rings"] = "anillos del Vacío^mp",
    ["Dealing damage with a Bash or fully-charged Heavy Attack places the <<1>> on your target for <<2>>. While active, you gain <<3>>, increasing damage done by <<4>>, and deal <<5>> more damage to the target and <<6>> less damage to all other enemies. If the enemy dies while marked, you gain <<7>> Stamina or Magicka, based off your highest maximum resource. This effect can trigger up to every <<8>>."] = "Al infligir daño con aporreo o con un ataque pesado completamente cargado, pones <<A:1>> en tu objetivo durante <<2>>. Mientras <<A:1>> está <<1{activo/activa}>>, obtienes <<3>>, que aumenta el daño infligido un <<4>>, e infliges un <<5>> de daño adicional al enemigo marcado y un <<6>> menos de daño al resto de enemigos. Si el enemigo muere mientras está marcado, te otorga <<7>> de aguante o magia, según tu recurso con el máximo más alto. Este efecto puede ocurrir cada <<8>> como máximo.",
    ["Quake"] = "terremoto^m",
    ["Stop"] = "alto",
    ["Remove"] = "eliminar",
    ["Visability"] = "visibilidad^f",
    ["Mor Naril Priory"] = "priorato de Mor Naril^m",
    ["Note to Gabrielle"] = "nota a Gabrielle^f",
    ["Search"] = "Registrar",
    ["Orsimer Hammer"] = "martillo orsimeri^m",
    ["Destroy"] = "Destruir",
    ["Mural Dedication"] = "dedicatoria de mural^f",
    ["Cube Reset"] = "reinicio de cubos^m",
    ["Seasons of the Worm Cult Part Two Trophies"] = "Trofeos de Seasons of the Worm Cult Part Two",
    ["Writhing Fortress"] = "fortaleza convulsa^f",
    ["Currency Vault"] = "Cámara de monedas",
    ["The currency vault dynamically shows the amount of gold you currently have. As you earn more gold, more shows up inside the vault. As you spend gold, less gold appears inside the vault."] = "La cámara de monedas muestra de forma dinámica la cantidad actual de oro que tienes. A medida que consigas más oro, este se irá acumulando en la cámara.",
    ["Bank Safe"] = "Caja fuerte del banco",
    ["Gain access to the bank safe by acquiring 3,000 favor with your pledged faction. Once acquired, you can access your bank and guild bank via this safe."] = "Gain access to the bank safe by acquiring the <TBD item/collectible>. Once acquired, you can access your bank and guild bank via this safe.",
    ["Faction Banners"] = "Estandartes de la facción",
    ["Display your allegiance to your faction. After gaining 2,000 favor with your faction, unlock the ability to display their banners in your courtyard."] = "Exhibe la lealtad que sientes por tu facción. Tras obtener <final amount pending> de favor con tu facción, desbloquearás la capacidad de mostrar sus estandartes en tu patio.",
    ["Defeat Soulcaller, Voidmother of Coldharbour, at Soulcaller's Haunt."] = "Derrota a Llamadora de Almas, madre del Vacío de Puerto Gélido, en el refugio de Llamadora de Almas.",
    ["The Worm Cult trapped four Undaunted heroes within soul-forged weapons across Solstice. Free the trapped heroes and learn the truth of their tale in a melancholy tome."] = "El Culto del Gusano ha atrapado a cuatro héroes de los Intrépidos en el interior de armamento forjado con almas por todo Solsticio. Libera a los héroes atrapados y descubre la verdad de su historia en un tomo melancólico.",
    ["Defeat Soulcaller, Voidmother of Coldharbour"] = "Derrota a Llamadora de Almas, madre del Vacío de Puerto Gélido",
    ["You have life again. Use it and move forward. Without sadness. Without regret."] = "Vuelves a tener una vida. Úsala y sigue adelante. Sin tristeza. Sin pesar.",
    ["I smell blood in the water. It's time to fight!"] = "El agua huele a sangre. ¡Es hora de luchar!",
    ["No! Just when Sharadak had her in his clutches, she slips away. Torment! Madness! This one may never recover! … Which way did she go?"] = "¡No! Justo cuando Sharadak la tenía en sus garras, se escapa. ¡Tormento! ¡Locura! ¡Puede que este khajiita nunca se recupere! ¿Por dónde se ha ido?",
    ["Well, maybe I'll … I'll just scrap this song."] = "Bueno, creo que será mejor... que deseche esta canción.",
    ["Vanus's dupe and Meridia's fool. Have you come to witness my triumph?"] = "<<player{El memo/La mema}>> de Vano y el tonto de Meridia. ¿Habéis venido a presenciar mi triunfo?",
    ["Come on, Jeetra—give me a little credit. I'm just looking. Something's off about this door, I'm trying to figure out what."] = "Venga, Jeetra, confía un poco en mí. Solo estoy echando un vistazo. Esta puerta tiene algo extraño; intento averiguar de qué se trata.",
    ["Destroy the soul flayer, mainlander! It blocks our path!"] = "¡Destruye el desollador de almas, continental! ¡No nos deja avanzar!",
    ["When you have the Embellished Dance Card, Rosy Boutonniere, and Sanguine's Goodbye Kiss: \nUse to combine into the Roseblood Wings Recall customized action."] = "Cuando tengas la tarjeta de baile adornada, el adorno para ojal róseo y el beso de despedida de Sanguine, combínalos para obtener la acción personalizada retirada de alas de sangre rósea.",
    ["Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."] = "La ofrenda de la Nueva Vida de hoy está entregada. Debería hablar con Lanullin sobre mi recompensa.",
    ["I delivered the New Life offering to Lanullin's elder. I should let her know I completed my task."] = "He entregado la ofrenda de la Nueva Vida a la persona anciana que me indicó Lanullin. Debería avisarla de que he completado el trabajo.",
    ["I need to prepare a banana surprise offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Tengo que preparar una ofrenda de sorpresa bananera para el anciano que me ha indicado Lanullin. Las tiendas de comestibles y las tabernas cercanas deberían contar con recetas y fogones en caso de que los necesite.",
    ["I need to prepare a carrot soup offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Tengo que preparar una ofrenda de sopa de zanahoria para la anciana que me ha indicado Lanullin. Las tiendas de comestibles y las tabernas cercanas deberían contar con recetas y fogones en caso de que los necesite.",
    ["I need to prepare a baked potato offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Tengo que preparar una ofrenda de patata asada para el anciano que me ha indicado Lanullin. Las tiendas de comestibles y las tabernas cercanas deberían contar con recetas y fogones en caso de que los necesite.",
    ["Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."] = "Es hora de entregar la ofrenda. La lista que me dio Lanullin debería indicar a quién y dónde tengo que llevarla.",
    ["Tibarr wants me to steal a coin from the lair of Rawl'kha's Dragon. He mentioned the lair was in a cavern nearby."] = "Tibarr quiere que robe una moneda en la guarida del dragón de Rawl'kha. Dice que la guarida se encuentra en una caverna cercana.",
    ["I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."] = "He completado el festejo de la Nueva Vida de Tibarr y le he entregado la moneda al mendigo orco. Ahora, tengo que pedirle a Tibarr mi recompensa.",
    ["I swiped the Dragon's coin and donated it to the Orc beggar. Now I should report back to Tibarr."] = "Le he birlado la moneda al dragón y se la he donado al mendigo orco. Ahora, tengo que volver a hablar con Tibarr.",
    ["I swiped the Dragon's coin. Tibarr wants me to give it to the Orc beggar, Yarg. I should talk to him and give him the coin."] = "Le he birlado la moneda al dragón. Tibarr quiere que se la dé a Yarg, un mendigo orco. Debería hablar con él y entregársela.",
    ["Yesei last saw the Dakoi in the streams near Stormhold's outskirts. I should start fishing there."] = "Yesei vio al Dakoi por última vez en los riachuelos que están cerca de Fuerte de la Tormenta. Debería empezar pescando allí.",
    ["I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."] = "Le he traído a Yesei el pez que me ha dado el Dakoi. Debería hablar con él sobre mi recompensa.",
    ["I caught the Dakoi, revealed to be an Argonian acting like a fish. He gave me one to hand to Yesei. I should return to him."] = "He capturado al Dakoi, que ha resultado ser un argoniano que se hace pasar por pez. Me ha dado un pez auténtico para que se lo entregue a Yesei. Debería regresar con él.",
    ["Dailonda said she needs fresh mud to spring the Mudman to life. Time to dig."] = "Dailonda ha dicho que necesita barro fresco para darle vida al Hombre de Barro. Toca escarbar.",
    ["I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."] = "He embadurnado con barro la efigie del Hombre de Barro para ayudar a Dailonda a terminarla. Debería hablar con ella sobre mi recompensa.",
    ["Mahagog said I could find an Orsimer hammer to use for the challenge at a blacksmith's station in the fortress. I should get it and try to smash the Oblivion boulder."] = "Mahagog ha dicho que puedo encontrar un martillo orsimeri en la herrería de la fortaleza para usarlo en el desafío. Debería tomarlo e intentar machacar el peñasco de Oblivion con él.",
    ["I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."] = "He demostrado mi fuerza y destruido el peñasco de Oblivion. Es hora de hablar con Mahagog sobre mi recompensa.",
    ["I need to find some honeycomb to put Garth in a good mood for New Life. The hermit said the forests near Hunter's Glade should have some."] = "Tengo que encontrar un panal para que Garth se ponga de buen humor por la Nueva Vida. El ermitaño dice que habrá alguno en los bosques cercanos al Claro del Cazador.",
    ["I fed Garth the honeycomb and saved all of Tamriel, according to the hermit. I should speak to him and ask about my reward."] = "Le he dado de comer el panal a Garth y he salvado todo Tamriel, según el ermitaño. Debería hablar con él sobre mi recompensa.",
    ["I need to fill the waterskin with Yokuda's waters in the west. Once done, I can perform the ritual of Anseilak at Motalion Necropolis."] = "Tengo que llenar el odre con agua de Yokuda, que se encuentra al oeste. Cuando lo haya hecho, podré realizar el ritual del Anseilak en la necrópolis de Motalion.",
    ["I helped Hassavir complete his pilgrimage and performed Anseilak for the fallen Yokudan mages. I should speak to him and ask about my reward."] = "He ayudado a Hassavir a concluir su peregrinaje y he realizado el Anseilak para los magos yokudanos caídos. Debería hablar con él y pedirle mi recompensa.",
    ["Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."] = "Lanullin está preparando sus ofrendas para los ancianos en Auridon. Debería hablar con ella y averiguar cómo puedo ayudarla.",
    ["I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."] = "Debería viajar a Rawl'kha y buscar a Tibarr para informarme más sobre su festejo de la Nueva Vida.",
    ["I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."] = "Debería buscar a Yesei en Fuerte de la Tormenta y ver si necesita ayuda para capturar al Dakoi.",
    ["I should speak to Dailonda in Elden Root to find out more about what she needs help with."] = "Debería hablar con Dailonda en Raíz de Elden para descubrir más detalles sobre la ayuda que necesita.",
    ["Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."] = "Mahagog está celebrando un festejo con un grupo de orcos en la fortaleza de Diente de Piedra. Debería hablar con él y descubrir más cosas sobre este concurso de fuerza.",
    ["The traveler was said to be seen out in Sentinel asking for help. I should start there and speak to them."] = "Dicen que han visto a la persona viajera pidiendo ayuda en Centinela. Debería empezar por ahí para que podamos hablar.",
    ["Anicus mentioned the hermit was spotted in the Rift. I should speak to him and learn more about his pet bear's needs."] = "Anico ha mencionado que han visto al ermitaño en La Grieta. Debería hablar con él y averiguar qué necesita su oso.",
    ["I helped Jahesi perform Anseilak and gave peace to the fallen Yokudan mages. I should speak to her about my reward."] = "He ayudado a Jahesi a realizar el Anseilak y brindar descanso a los magos yokudanos caídos. Debería hablar con ella sobre mi recompensa.",
    ["I need bait to catch the Dakoi fish. Yesei mentioned the Shadowscale camp west from Stormhold might have a bottle of bloodwine that could work."] = "Necesito cebo para capturar al Dakoi. Yesei ha mencionado que, en el campamento de los Escamas Sombrías que hay al oeste de Fuerte de la Tormenta, podría haber una botella de vino de sangre que serviría.",
    ["Mahagog mentioned he fought a group of Daedra west of Stonetooth Fortress that left behind an Oblivion boulder for us to smash. I should search the area, find the boulder, and mark its location on my map."] = "Mahagog ha mencionado que luchó contra un grupo de daedra al oeste de la fortaleza de Diente de Piedra; tras el enfrentamiento, quedó un peñasco de Oblivion que podemos machacar. Debería buscar el peñasco en esa zona y marcar su ubicación en el mapa.",
    ["I found the strange Oblivion boulder. I should return to Mahagog and let him know exactly where it is."] = "He encontrado el extraño peñasco de Oblivion. Debería volver con Mahagog y contarle dónde está exactamente.",
    ["Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."] = "Mahagog me está esperando. Debería hablarle del peñasco que he encontrado para nuestro desafío.",
    ["Sirilonwe noticed an abandoned camp to the southeast. She guesses that it might belong to Terinvel and Ormard. I should search it for evidence of where they went."] = "Sirilonwe ha visto un campamento abandonado al sudeste. Cree que podría ser el de Terinvel y Ormard. Debería registrarlo para buscar pistas que indiquen adónde han ido.",
    ["I offered Sirilonwe advice about how to handle Terinvel's transformation into a vampire. It remains to be seen if she takes it. I should talk to her about my reward."] = "Le he dado un consejo a Sirilonwe sobre cómo lidiar con la transformación de Terinvel en vampiro. Veremos si lo acepta. Debería hablar con ella sobre mi recompensa.",
    ["The abandoned campsite outside Ashbound Hall definitely belonged to Terinvel and Ormard. I found notes from them claiming to know of a side entrance into the Hall. I should talk to Sirilonwe about this."] = "No cabe duda de que el campamento abandonado a las afueras del Salón Cinéreo pertenecía a Terinvel y Ormard. Unas notas abandonadas afirmaban que habían encontrado una entrada secundaria al Salón Cinéreo. Debería hablar con Sirilonwe al respecto.",
    ["Terinvel's dropped note describes a cave entrance that leads inside Ashbound Hall. I should explore to the southwest to find it."] = "La nota que dejó Terinvel describe la entrada de una cueva que conduce al interior del Salón Cinéreo. Debería explorar la zona sudoeste para encontrarla.",
    ["I found a crack in the stone that could lead into some caves. This might be the side entrance into Ashbound Hall that Terinvel mentioned in his notes. I should head in and see where it leads me."] = "He encontrado una grieta que podría conducir a unas cuevas. Podría tratarse de la entrada secundaria al Salón Cinéreo que Terinvel mencionaba en sus notas. Debería entrar para ver adónde lleva.",
    ["A Stirk Fellowship scout named Mihnassi told me about the missing Terinvel and Sirilonwe's need for aid. She said I could find the academic on the road north of Ashbound Hall. I should track her down."] = "Una exploradora de la Hermandad de Stirk llamada Mihnassi me ha contado que Terinvel ha desaparecido y Sirilonwe necesita ayuda. Me ha dicho que puedo encontrar a la erudita en el camino que discurre por el norte del Salón Cinéreo. Debería ir a buscarla.",
    ["The crack in the wall led into a cave. I see an opening to a building that may be Ashbound Hall. I should talk to Sirilonwe to discuss our next move."] = "La grieta del muro conducía a una cueva. Veo una abertura que da a un edificio que podría ser el Salón Cinéreo. Debería hablar con Sirilonwe sobre qué hacer a continuación.",
    ["Sirilonwe confirmed that the cave opens into Ashbound Hall. She urged caution as we explore the prison. Vampires lurk everywhere. I should start my search for Terinvel."] = "Sirilonwe ha confirmado que la cueva conduce al Salón Cinéreo. Quiere que extrememos la cautela al explorar la prisión, pues los vampiros acechan por todas partes. En primer lugar, debería buscar a Terinvel.",
    ["My search revealed a medallion etched with strange characters. I also found a note describing a method to unlock the sealed door. I need to show these to Sirilonwe."] = "He encontrado un medallón con unos caracteres extraños grabados, así como una nota que explica cómo abrir la puerta sellada. Debo enseñárselos a Sirilonwe.",
    ["Sirilonwe identified the medallion I found as the Aspect of Brutality. It's part of a system that unlocks doors around Ashbound Hall. The note I found describes the Aspect's correct arrangement. I should place this on the unlocking"] = "Sirilonwe ha identificado el medallón que encontré como el aspecto de brutalidad, que forma parte de un sistema para abrir puertas en el Salón Cinéreo. La nota que hallé indica la disposición correcta de los aspectos. Debería colocar este en el mecanismo.",
    ["A young vampire revealed herself to us and claimed she meant no harm. It seems she's the source of the mysterious whispering we heard. I should find out why she's following us."] = "Una joven vampira ha aparecido ante <<player{nosotros/nosotras}>> y afirma que no tiene intención de hacernos daño. Parece que es la fuente de los susurros misteriosos que escuchamos. Debería averiguar por qué nos está siguiendo.",
    ["Azartha gave us some helpful information for dealing with Ashbound Hall. Rooms that are more brightly lit than others will keep us safe. Apparently we can find a map in one of those rooms. I should resume my search of the prison."] = "Azatha nos ha dado información útil para lidiar con el Salón Cinéreo. Las salas con mayor iluminación nos mantendrán a salvo y, al parecer, una de ellas contiene un mapa. Debería seguir registrando la prisión.",
    ["We found another room bathed in purple light. Azatha mentioned we might find a map for Ashbound Hall in a room like this. I should search for one."] = "Hemos encontrado otra sala iluminada con luz morada. Azatha dijo que, en una sala como esta, podría haber un mapa del Salón Cinéreo. Debería buscarlo.",
    ["Our exploration of Ashbound Hall brought us to a magically sealed door. We found a safe room nearby that could provide clues to opening the door. I should look around for anything that stands out."] = "La exploración del Salón Cinéreo nos ha llevado hasta una puerta sellada mediante la magia. Hemos encontrado una sala segura donde podría haber pistas sobre cómo abrir la puerta. Debo buscar cualquier cosa que me llame la atención.",
    ["During my search for a map of Ashbound Hall, I also found another Aspect medallion. Maybe Sirilonwe can tell me which one it is. I should show it to her along with the map."] = "Mientras buscaba un mapa del Salón Cinéreo, también he encontrado otro medallón de aspecto. Tal vez Sirilonwe pueda decirme de cuál se trata. Debería enseñárselo junto con el mapa.",
    ["As Sirilonwe and I crossed a bridge, we heard whispering from the shadows. The whispers seem to be talking about us. I should hunt down the source to see if its dangerous."] = "Mientras Sirilonwe y yo cruzábamos un puente, oímos susurros que venían de las sombras. Parecía que hablaban de <<player{nosotros/nosotras}>>. Debería localizar la fuente para ver si entraña algún peligro.",
    ["With the help of Sirilonwe's spell, I was able to clear the rubble from the bridge. Now I can continue my search of Ashbound Hall for Terinvel."] = "Con la ayuda del hechizo de Sirilonwe, he logrado apartar los escombros del puente. Ahora, puedo seguir buscando a Terinvel en el Salón Cinéreo.",
    ["We entered a new section of Ashbound Hall and found another vampire calling out for help. Like Azatha, he claims to be harmless and didn't attack on sight. I should talk to him to see if he can provide information for finding Terinvel."] = "Hemos accedido a un nuevo sector del Salón Cinéreo y hemos encontrado a otro vampiro pidiendo ayuda. Al igual que Azatha, asegura ser inofensivo y no nos ha atacado nada más vernos. Debería hablar con él y ver si puede darnos información para encontrar a Terinvel.",
    ["Despite Sirilonwe healing Liviano, he decided to attack us. She turned him into ashes. I should search his remains to see if he did have the Aspect he claimed to."] = "A pesar de que Sirilonwe lo curase, Livanio ha decidido atacarnos y ella lo ha reducido a cenizas. Debería examinar sus restos para ver si tenía el aspecto que aseguraba poseer.",
    ["Fortunately, I found an Aspect among Livanio's ashes. Lucky for us, Sirilonwe's fire spell didn't melt it. I should check on her to make sure she's all right after this attack."] = "Afortunadamente, he encontrado un aspecto entre las cenizas de Livanio. Hemos tenido suerte de que el hechizo de fuego de Sirilonwe no lo haya derretido. Debería hablar con ella para cerciorarme de que ha salido ilesa del ataque.",
    ["We unlocked the door by using the Aspects, and entered the next section of Ashbound Hall. Now we can continue our search of this prison for Terinvel."] = "Tras abrir la puerta utilizando los aspectos, hemos accedido al siguiente sector del Salón Cinéreo. Ahora, podemos seguir registrando la prisión en busca de Terinvel.",
    ["Sirilonwe feels justified in killing Livanio in self-defense. Plus, now we have another important Aspect to help us through this prison. I should follow her into the next section."] = "Sirilonwe considera que ha matado a Livanio en legítima defensa. Además, ahora contamos con otro aspecto importante para movernos por la prisión. Debería seguirla hasta el siguiente sector.",
    ["The injured Ormard implied that he hid an Aspect somewhere in the central courtyard. I need to look through all this damage until I find it."] = "Ormard, que está herido, ha insinuado que ocultó un aspecto en alguna parte del patio central. Tengo que rebuscar entre todos los desperfectos hasta encontrarlo.",
    ["I managed to find an Aspect among the rubble of the central courtyard. Ormard didn't do that good of a job hiding it. I should show it to Sirilonwe."] = "He logrado encontrar un aspecto entre los escombros del patio central. Ormard no se ha esmerado demasiado a la hora de ocultarlo. Debería mostrárselo a Sirilonwe.",
    ["The only way out of the central courtyard is through another magically sealed door. I need to place the Aspects in the proper order to unlock the magic."] = "La única forma de salir del patio central es atravesando otra puerta sellada con magia. Tengo que colocar los aspectos en el orden correcto para anular el cierre mágico.",
    ["We finally caught up with Terinvel. Unfortunately, a powerful vampire named the Elder has captured and bound him. I only see one way to get him free. I should kill the Elder."] = "Al fin hemos dado con Terinvel. Por desgracia, una vampira poderosa, llamada «la Anciana», lo ha capturado e inmovilizado. Solo veo una forma de liberarlo: matando a la Anciana.",
    ["Terinvel is free, even if he doesn't immediately appreciate it. Sirilonwe conjured a portal so that we can leave Ashbound Hall. I should join her outside."] = "Terinvel es libre, aunque no parece apreciarlo. Sirilonwe ha conjurado un portal que nos permitirá salir del Salón Cinéreo. Debería reunirme con ella fuera.",
    ["I stepped through the portal and arrived outside Ashbound Hall. I can hear Terinvel and Sirilonwe argue with each other. I should check on the newly rescued researcher and see how he feels."] = "He cruzado el portal y he llegado al exterior del Salón Cinéreo. Parece que Terinvel y Sirilonwe están discutiendo. Debería hablar con el investigador recién rescatado para ver cómo se encuentra.",
    ["Despite all our efforts, Terinvel didn't escape unscathed. He admits that the Elder passed on vampirism to him. He seems quite excited about the power growing inside him. I should talk to Sirilonwe about this."] = "Pese a nuestros esfuerzos, Terinvel no ha salido indemne: admite que la Anciana le ha contagiado el vampirismo y parece entusiasmarle el poder que se está gestando en su interior. Debería tratar el asunto con Sirilonwe.",
    ["After Sirilonwe cast her spell, ghostly versions of Terinvel and Ormard appeared. This was a recreation of a moment in the past. They discussed their plans to go deeper into the Ashbound Halls. I should talk to Sirilonwe about this."] = "Después de que Sirilonwe lanzara su hechizo, aparecieron unas versiones fantasmales de Terinvel y Ormard que recrearon un momento del pasado en el hablaban sobre sus planes de adentrarse en el Salón Cinéreo. Debería hablar con Sirilonwe de esto.",
    ["With our combined strength, Sirilonwe and I managed to defeat the Elder. Terinvel is now free, if a bit ungrateful. I should wait until he's on his feet to see what we do next."] = "Aunando nuestras fuerzas, Sirilonwe y yo hemos logrado derrotar a la Anciana. Terinvel está libre, pero no se muestra demasiado agradecido. Debería esperar a que se levante para ver qué hacer a continuación.",
    ["When I placed the Aspect of Brutality into the mechanism, the ward disappeared from the door. Sirilonwe and I should continue our search of Ashbound Hall for Terinvel."] = "Al colocar el aspecto de brutalidad en el mecanismo, la custodia de la puerta se ha disipado. Sirilonwe y yo deberíamos seguir registrando el Salón Cinéreo en busca de Terinvel.",
    ["Now that we have a rough map of Ashbound Hall, finding Terinvel should be slightly easier. Time to continue forward with our search."] = "Ahora que contamos con un mapa aproximado del Salón Cinéreo, debería resultarnos un poco más sencillo encontrar a Terinvel. Es hora de retomar la búsqueda.",
    ["Sirilonwe has a spell that can clear the rubble that blocks our path. Once she starts casting, I need to smash the rubble."] = "Sirilonwe posee un hechizo capaz de retirar los escombros que nos cierran el paso. Tengo que golpearlos en cuanto empiece a lanzarlo.",
    ["Sirilonwe and I finally reached the central courtyard and it's in shambles. However, we did manage to find an injured Ormard laying on the ground. He claims to have expected us. I should press him to tell me where Terinvel went."] = "Por fin, Sirilonwe y yo hemos llegado al patio central, que está hecho un desastre. Sin embargo, hemos encontrado a Ormard herido y tendido en el suelo. Asegura que nos estaba esperando. Debería presionarlo para que me diga adónde ha ido Terinvel.",
    ["Sirilowe spotted a camp fire tucked away in a heavily damaged area of the Hall. She thinks it's worth searching. I should look through the camp for any clues."] = "Sirilonwe ha descubierto un campamento oculto en una zona del Salón Cinéreo con graves desperfectos. Cree que vale la pena echar un vistazo. Debería registrarlo para buscar pistas.",
    ["Ashbound Hall's crash landing into Solstice created rubble everywhere. Some of it blocks a bridge we need to cross. I should talk to Sirilonwe about how to clear it."] = "El impacto del Salón Cinéreo contra Solsticio ha esparcido escombros por todas partes; unos cuantos están bloqueando el puente que tenemos que cruzar. Debería hablar con Sirilonwe sobre cómo deshacernos de ellos.",
    ["I found a hat that Sirilonwe claims belong to Ormard. Apparently it spurred an idea in her. I should watch what comes from her spell."] = "He encontrado un sombrero que, según Sirilonwe, pertenece a Ormard. Parece que le ha dado una idea. Debería ver qué efectos tiene su hechizo.",
    ["In the memory that Sirilonwe recreated, Ormard wanted to get to a crater that's just ahead. Now we have a direction for a search. I should find this crater."] = "En el recuerdo que ha recreado Sirilonwe, Ormard quería llegar hasta un cráter que se encuentra un poco más adelante. Ahora sabemos dónde buscar. Debería hallar el cráter.",
    ["We reached the area of Ashbound Hall that Ormard referred to as a crater. It certainly matches the title. Should continue my search for Terinvel by crossing it."] = "Hemos llegado a la zona del Salón Cinéreo que Ormard denominaba «cráter» y es innegable que el nombre le hace justicia. Debería atravesarlo para seguir buscando a Terinvel.",
    ["We crossed through the crater, but saw no sign of Terinvel or Ormard. Sirilonwe suggested we keep heading in this direction. Perhaps we're hot on their heels. I should continue my search of Ashbound Hall."] = "Hemos atravesado el cráter, pero no hemos hallado ningún rastro de Terinvel ni de Ormard. Sirilonwe ha sugerido que sigamos avanzando en la misma dirección. Tal vez estemos pisándoles los talones. Debería continuar registrando el Salón Cinéreo.",
    ["Sirilonwe and I came across another door sealed with magic. Looks like I need to use the Aspects we collected to unlock it. I should find the right placement for the medallions to unlock the door."] = "Sirilonwe y yo hemos encontrado otra puerta sellada con magia. Parece que, para abrirla, tenemos que utilizar los aspectos que hemos conseguido. Debería averiguar en qué orden hay que colocar los medallones para abrir la puerta.",
    ["I placed all the Aspects in their proper spot and unlocked the door. According to Ormard, Terinvel should be just beyond, but he'll be in the company of someone called the Elder. I should go confront her so we can get out of here."] = "He colocado cada aspecto en su lugar correcto y he abierto la puerta. Según Ormard, Terinvel debería estar justo al otro lado, aunque en compañía de una tal «Anciana». Debería ir a plantarle cara para que podamos salir de aquí.",
    ["For Lanullin, celebrating New Life involves giving back to the esteemed elders of her community through good meals. I agreed to help her prepare and deliver them."] = "Para Lanullin, celebrar la Nueva Vida consiste en corresponder a los ancianos de su comunidad que más aprecia con buenas comidas. He aceptado ayudarla a prepararlas y entregarlas.",
    ["Food for New Life"] = "Alimentos para la Nueva Vida",
    ["I met a Khajiit in Rawl'kha who asked me to try and steal coin from a Dragon for his New Life festivity, and then give it to a needy Orc nearby. Apparently, its tricks are challenging to some. I agreed to participate."] = "Un khajiita que he conocido en Rawl'kha me ha pedido que intente robarle una moneda a un dragón para su festejo de la Nueva Vida y que, luego, se la entregue a un orco necesitado de la zona. Al parecer, sus trucos resultan complicados para algunos. He aceptado participar.",
    ["The Dragon's Hoard"] = "El tesoro del dragón",
    ["I met an Argonian angler in Stormhold frustrated over not being able to catch the Dakoi, a special fish that's said to appear every New Life festival and bring good fortune. I agreed to hunt and catch the Dakoi for him."] = "He conocido a un pescador argoniano en Fuerte de la Tormenta que está frustrado por no ser capaz de pescar al Dakoi, un pez especial que, según dicen, aparece cada Festival de la Nueva Vida y trae buena suerte. He accedido a atrapar al Dakoi en su lugar.",
    ["The Hunt for Dakoi"] = "La caza del Dakoi",
    ["I met a Wood Elf in Grahtwood trying to construct a Mudman effigy for the New Life festival to bless all of Tamriel's green. I agreed to help her gather mud and complete the effigy since her kin aren't there to help."] = "He conocido a una bosmer en el Bosque Graht que quiere construir una efigie del Hombre de Barro para el Festival de la Nueva Vida con el propósito de que bendiga todo el verdor de Tamriel. He accedido a echarle una mano para recoger barro y completar la efigie, ya que su familia no está aquí para ayudarla.",
    ["The Mudman"] = "El Hombre de Barro",
    ["I met a group of Orcs in Stonetooth Fortress breaking boulders for Betnikh's Boon during the New Life Festival. Their leader proposed I search an area where he fought Daedra for a stronger boulder to break. I accepted his challenge."] = "Me he encontrado con un grupo de orcos que estaban destrozando peñascos en la fortaleza de Diente de Piedra para conseguir la bendición de Betnikh durante el Festival de la Nueva Vida. Su líder me ha propuesto que busque un peñasco más duro que romper en una zona donde luchó contra un grupo de daedra. He aceptado su desafío.",
    ["Betnihk's Boon"] = "La bendición de Betnikh",
    ["A member of the Skaal tribe believes the mood of his bear, Garth, during New Life, will determine the fate of Tamriel. He believes honeycomb might make him happy. I agreed to help him."] = "Un miembro de la tribu Skaal cree que el humor de su oso, Garth, durante la Nueva Vida determinará al futuro de Tamriel. Piensa que se pondrá contento con un panal. He accedido a ayudarlo.",
    ["The Judgment of Garth"] = "El juicio de Garth",
    ["I met a wandering traveler out in Sentinel on pilgrimage to give fallen Yokudan mages Anseilak, a ritual that brings them peace. However, since he's unable to complete the journey, I agreed to help him."] = "He conocido a un viajero en Centinela que está peregrinando para realizar por los magos yokudanos caídos el Anseilak, un ritual que les dará descanso. Sin embargo, como no puede completar el viaje, he accedido a ayudarlo.",
    ["The Desert and the Sea"] = "El desierto y el mar",
    ["Two academics, Sirilonwe and Terinvel, came to study Ashbound Hall, a vampire prison that arrived with the planemeld on Solstice. However, Terinvel went missing and Sirilonwe needs help finding him among the deadly vampires."] = "Sirilonwe y Terinvel son dos eruditos que han venido a estudiar el Salón Cinéreo, una prisión para vampiros que llegó a Solsticio con la fusión de planos. Terinvel ha desaparecido y Sirilonwe necesita ayuda para encontrarlo entre los letales vampiros.",
    ["Antique Map of Solstice"] = "mapa antiguo de Solsticio^m",
    ["A simple stone for a complex task. To connect a family through the ages. Stone is chipped to have many small indentations. Stone-Nest tradition says each face retains some flavor, some memory, of meals past."] = "Una piedra sencilla para una tarea compleja: conectar a una familia a través de los siglos. La piedra está labrada con multitud de pequeñas muescas. La tradición de los Nido Pétreo afirma que cada cara conserva algo de sabor o algún recuerdo de los almuerzos pasados.",
    ["Five is a number that comes up a lot with Hircine. These fangs represent the Spear of Bitter Mercy, also called Spear with Five Points. They would have been fixed in a warmask belonging to a great chief of the Ket Keptu."] = "El cinco es un número muy asociado a Hircine. Estos colmillos representan la Lanza de la amarga misericordia, también llamada Lanza de cinco puntas. Habrían estado sujetos a una máscara de guerra perteneciente a un gran jefe de los ket keptu.",
    ["Ah, of course! The Ket Keptu were hunters and warrior-smiths, a people devoted to the Lord of the Hunt. To carry the Spear of Bitter Mercy was a high honor for their great champions. Whoever wore this warmask was indeed favored by Hircine!"] = "¡Ah, por supuesto! Los ket keptu eran cazadores y guerreros-herreros, un pueblo fiel al Señor de la Caza. Portar la Lanza de la amarga misericordia era un enorme privilegio para sus grandes campeones. ¡Sin duda, quienquiera que llevase esta máscara de guerra gozaba del favor de Hircine!",
    ["At first glance, I thought this might be a soul gem. But holding it felt so strange! The crystal almost pulses like a beating heart on fire! And yet it feels so empty. Soul Gems have a different warmth."] = "A primera vista, pensé que esto podría ser una gema de alma, pero ¡me dio una sensación muy extraña al sostenerlo! ¡El cristal parece palpitar como un corazón en llamas! Y, sin embargo, da la impresión de estar vacío. Las gemas de alma emiten un calor diferente.",
    ["I practice conjuration magic."] = "Soy <<player{brujo/bruja}>> y practico magia de conjuración.",
    ["Day 1\n\nNo wonder we're the only fools willing to walk into this deathtrap. This side of Solstice is nothing but destruction. Thankfully, some soldiers from this Stirk Fellowship helped us avoid some Daedra and a Worm Cult patrol.\n\n Sadryn promises a fortune so big I'll never have to open my toolbox again. And he really means it. After we finish this job and I hand over my trap designs, they're his for good.\n\nHonestly, it feels like giving up part of my identity, but mother needs the gold. I hate seeing her like this. She barely even recognizes me anymore. Her ailment is worsening.\n\n* * *\nDay 2\n\nWe finally made camp in some relatively calm part of Eastern Solstice, and yet my mind still battles over whether I can actually fulfill my end of this bargain. No, I'm sure now.\n\nI'll set the traps tomorrow, but I've decided I can't part with my plans for how to build them. Father helped me design these. Building every trap makes it feel like he's still with me, and mother wouldn't want me to sell my knowledge like this, either.\n\nI'll tell Sadryn and still help him complete this hunt. I need the gold. But after that we'll need to settle on a new deal.\n\n* * *\nSadryn became so angry when I told him, he went completely mad! Oh gods, he stabbed me! I managed to slash his chest, drive him off. I should have aimed for his heart.\n\nIt hurts so much. The blood won't stop flowing. I'm hiding, but I hear him looking for me. It's getting harder to write.\n\nMother, I'm sor—"] = "Día 1\n\nNo me sorprende que seamos los únicos idiotas dispuestos a lanzarnos de cabeza a esta trampa mortal. En este lado de Solsticio, solo hay destrucción. Por suerte, algunos soldados de la Hermandad de Stirk nos han ayudado a evitar a unos daedra y a una patrulla del Culto del Gusano.\n\n Sadryn promete una fortuna tan colosal que nunca tendré que volver a abrir mi caja de herramientas. Y lo dice en serio. Tras terminar este encargo y entregarle mis diseños de trampas, se los quedará para siempre.\n\nLa verdad es que siento que estoy cediéndole parte de mi identidad, pero mi madre necesita el oro. Odio verla así. Ya casi no me reconoce. Su aflicción está empeorando.\n\n* * *\nDía 2\n\nPor fin hemos acampado en una zona relativamente tranquila de Solsticio Oriental, pero mi mente sigue debatiéndose sobre si seré capaz de cumplir con mi parte de este trato. No, ahora lo veo claro.\n\nMañana pondré las trampas, pero he decidido que no puedo entregar sus planos de construcción. Mi padre me ayudó a diseñarlas. Montar cada trampa me hace sentir que sigue a mi lado, y a mi madre tampoco le gustaría que vendiera mis conocimientos así.\n\nSe lo diré a Sadryn y lo ayudaré a terminar esta cacería. Necesito el oro. Pero, después de eso, tendremos que negociar un nuevo trato.\n\n* * *\nSadryn se ha enfurecido tanto cuando se lo he contado... ¡Se ha vuelto completamente loco! ¡Por los dioses, me ha apuñalado! He conseguido asestarle una cuchillada en el pecho y se ha marchado. Tendría que haberle apuntado al corazón.\n\nMe duele muchísimo. No deja de brotar sangre. Me he escondido, pero lo oigo buscarme. Cada vez me cuesta más escribir.\n\nMadre, lo sie...",
    ["by Vastarie\n\nAll mages know the tale of the old rivalry between Vanus Galerion and Mannimarco. From their legendary quarrel arose both the Order of the Black Worm and the Mages Guild, societies that have dominated the practice of magic across Tamriel for centuries now. Yet before that, these two enemies were friends, Psijic students who excelled at Artaeum. Their brilliance illuminated the deepest secrets of our art and marked the way for countless mages who have followed since.\n\nWhen they first met, Mannimarco and Galerion quickly realized that they understood things none of their fellows did. Out of mutual respect friendship grew, at least for a time. Their good-natured debates on the secrets of magic were the wonder of Artaeum, drawing scores of spectators and setting forth principles that are still studied today.\n\nThis is a record of a debate now known as their Second Dialogue. It began as a discussion about whether the Consecrations of Arkay apply to soul magic.\n\n* * *\nVanus Galerion: Some things are forbidden, my friend, even to the most powerful of us—especially to the most powerful of us. I can slay with a mere word or gesture, but that does not give me permission to murder whenever I find it convenient to do so.\n\nMannimarco: I do not make that argument. Of course casual murder is wrong. Only those sick in the mind inflict pain without purpose.\n\nVanus Galerion: Your distinction about \"purpose\" would seem to excuse some cases of murder or torture. Or, to return to our initial question, the imprisonment of another being's soul.\n\nMannimarco: Imprisonment? I speak of borrowing a soul's power for a task measured in hours or days, when it will soon enough have the rest of eternity to go about its business, whatever that is. Since I am asking only for a little of something the soul now possesses an infinite abundance of—time, eternity!—the cost to the soul is nothing. It is hardly slavery.\n\nVanus Galerion: You would exact labor and pay nothing in return. Hours and days have a way of turning into years and centuries, I suspect. Because necromancy does not secure consent before binding the soul or using its power, it compels service that should be freely given or exchanged for something of worth.\n\nMannimarco: Ah, so it is the lack of consent that troubles you.\n\nVanus Galerion: Does it not trouble you?\n\nMannimarco: Many healing spells manipulate the recipient's animus. The soul, if you like. No one suggests that using magicka to reshape the animus for healing is wrong. But if the person we are trying to help is unconscious, they can hardly give their consent. Should we not aid them?\n\nVanus Galerion: If reason dictates that the injured party would desire aid, we can take their consent for granted.\n\nMannimarco: What if reason dictates that a soul might be willing to perform some service other than helping to heal itself? Imagine a warrior slain on the field of battle. His comrades are still in great danger; he would aid them if he could. The necromancer can give him that chance.\n\nVanus Galerion: A slippery slope. Necromancers have demonstrated again and again that Arkay's Blessing can be circumvented by underhanded means of securing consent. Or ignoring it, under the right conditions. That does not make it permissible.\n\nMannimarco: So your argument is that mages unconstrained by conscience can do things you find repugnant. Which is just as true for casual murder with a lightning bolt or a blast of frost as it is for binding souls. I submit there is nothing innately immoral about necromancy. A mage either chooses to wield his magic in a manner society deems acceptable, or he does not. The form hardly matters.\n\nVanus Galerion: This sounds familiar. You argued before that power has no morality.\n\nMannimarco: So I did."] = "De Vastarie\n\nTodos los magos conocen la antigua rivalidad entre Vano Galerion y Mannimarco. De su disputa legendaria surgieron la Orden del Gusano Negro y el gremio de magos, dos sociedades que han dominado la práctica de la magia en Tamriel durante siglos. Sin embargo, en el pasado, estos enemigos eran amigos, dos estudiantes de la Orden Psijic que destacaban en Arteum. Su brillantez iluminó los secretos más profundos de nuestro arte y marcó el camino que han seguido innumerables magos.\n\nCuando se conocieron, Mannimarco y Galerion comprendieron que entendían cosas que quedaban fuera del alcance de sus compañeros. De este respeto mutuo surgió la amistad, al menos durante un tiempo. En Arteum, sus afables debates sobre los secretos de la magia atrajeron a multitud de espectadores y establecieron una serie de principios que se siguen estudiando a día de hoy.\n\nEste es el registro de un debate que ahora se conoce como «el segundo diálogo». Comenzó siendo una conversación en la que intentaban determinar si las consagraciones de Arkay podían aplicarse a la magia de alma.\n\n* * *\nVano Galerion: Hay cosas que están prohibidas, amigo mío, incluso para los magos más poderosos; o mejor dicho, sobre todo para los magos más poderosos. Me basta con pronunciar una palabra o hacer un gesto para matar, pero eso no significa que pueda hacerlo cuando lo considere conveniente.\n\nMannimarco: No estoy diciendo eso. Por supuesto que asesinar está mal. Solo un enfermo mental infligiría dolor sin propósito.\n\nVano Galerion: Que hables de «propósito» me hace pensar que disculpas ciertos casos de asesinato o tortura o, retomando la cuestión inicial, el acto de aprisionar un alma.\n\nMannimarco: ¿Aprisionar? Estoy hablando de tomar prestado el poder de un alma para una tarea que se mide en horas o días, cuando pronto tendrá el resto de la eternidad para dedicarse a sus asuntos, sean cuales sean. Solo estoy pidiendo un poco de aquello que el alma posee en infinita abundancia (tiempo, ¡eternidad!), por lo que el coste para esta es nulo. No puede considerarse esclavitud.\n\nVano Galerion: La obligarías a trabajar sin darle nada a cambio. Y sospecho que las horas y los días acabarían convirtiéndose en años y siglos. Como la nigromancia no solicita el consentimiento del alma antes de vincularla o utilizar su poder, la compele a prestar un servicio que esta debería ofrecer libremente o intercambiar por algo de valor.\n\nMannimarco: Ah, de modo que lo que te preocupa es la falta de consentimiento.\n\nVano Galerion: ¿A ti no?\n\nMannimarco: Muchos hechizos curativos manipulan el ánima del receptor. El alma, si lo prefieres. Nadie sugiere que usar la magia para remodelar el ánima con fines curativos esté mal, pero si la persona a la que pretendemos ayudar está inconsciente, es difícil que pueda darnos su consentimiento. ¿Eso significa que no deberíamos ayudarla?\n\nVano Galerion: Si la razón dicta que la parte lesionada desearía recibir ayuda, se puede dar por sentado su consentimiento.\n\nMannimarco: ¿Y si la razón dicta que un alma estaría dispuesta a prestar otros servicios en lugar de a curarse? Imagina un guerrero muerto en el campo de batalla. Sus compañeros siguen corriendo peligro y él los ayudaría si pudiera. El nigromante puede brindarle esa oportunidad.\n\nVano Galerion: Es un terreno pantanoso. Los nigromantes han demostrado una y otra vez que la Bendición de Arkay se puede eludir recurriendo a medios deshonestos para obtener el consentimiento. O incluso ignorar por completo, si se dan las condiciones adecuadas. Eso es inaceptable.\n\nMannimarco: Así que tu argumento es que un mago que no se ve limitado por su conciencia puede hacer cosas que te resultan repugnantes, ya sea vincular un alma, o matar con un rayo o una explosión de hielo. Yo sostengo que no hay nada intrínsecamente inmoral en la nigromancia. Un mago puede ejercer su magia de una manera que la sociedad considere aceptable, o puede no hacerlo. La forma no importa.\n\nVano Galerion: Esto me resulta familiar. Ya argumentaste que el poder carece de moralidad.\n\nMannimarco: Efectivamente",
    ["Monthly report from Dark Adept Bruhlz.\n\nRecent Acquisitions:\n\n57 Stone-Nest Argonians taken from villages\n6 Escaped Stone-Nest Argonians, recaptured\n7 Stirk Fellowship soldiers \n1 Argonian necromancer, imprisoned for betraying the order\n\n<scribbled in a different hand>\nThe shackles need more souls to fully merge Coldharbour into this plane. And the improved devices must be tested. For that, we require more prisoners. If you cannot secure them, I will select volunteers from among the faithful in your nest.\n\nAnd make sure the traitor suffers. Sacrifice her last. Let her see what the flayers do to those she felt obligated to protect.\n\nMannimarco, King of Worms"] = "Informe mensual del adepto oscuro Bruhlz.\n\nAdquisiciones recientes:\n\n57 argonianos Nido Pétreo raptados en las aldeas\n6 argonianos Nido Pétreo huidos y recapturados\n7 soldados de la Hermandad de Stirk \n1 nigromante argoniana, encarcelada por traicionar a la orden\n\n<Garabateado con una letra diferente.>\nLos grilletes precisan más almas para fusionar por completo Puerto Gélido con este plano. Y hay que hacer pruebas con los dispositivos mejorados. Para ello, necesitamos más prisioneros. Si no los proporcionas, seleccionaré voluntarios entre los fieles de tu nido.\n\nY asegúrate de que la traidora sufre. Sacrifícala la última. Que vea lo que los desolladores les hacen a quienes sintió la obligación de proteger.\n\nMannimarco, rey de los Gusanos",
    ["To: Overseer Bazgrum, Kaz-Neesak Mine\nFrom: The Court of Mannimarco at Mor Naril\n\nBazgrum,\n\nMannimarco congratulates you on your successful tests of the new soul flayers. The number of souls already harvested meets minimum standards to proceed with our next steps in the processes. We are confident that the new soul flayers can be set to operate continuously, slaying all life that wanders into their range.\n\nOur next step will be to acquire the ancient dead of an Argonian tomb complex. Generations of interred bodies will swell the ranks of our undead army. Our \"special guest\" has arrived safely, and Mannimarco looks forward to his contribution to our endeavors. Upon completion of your tasks, gather your forces and meet the Worm King at the Argonian necropolis to the north. \n\nSpeed and diligence is always imperative in these matters, so do not shirk your duties."] = "Al supervisor Bazgrum de la mina Kaz-Neesak\nDe la corte de Mannimarco en Mor Naril\n\nBazgrum:\n\nMannimarco te felicita por el éxito de tus pruebas con los nuevos desolladores de almas. El número de almas ya cosechadas cumple los objetivos mínimos para que sigamos dando los pasos establecidos. Confiamos en que los nuevos desolladores de almas puedan ajustarse para que operen de forma continua y aniquilen toda forma de vida que entre en su radio de alcance.\n\nNuestro siguiente paso será hacernos con los muertos ancestrales de un complejo de tumbas argoniano. Generaciones de cadáveres pasarán a engrosar las filas de nuestro ejército de no muertos. Nuestro «invitado especial» ha llegado sano y salvo, y Mannimarco espera con impaciencia su contribución a nuestros empeños. Cuando hayas cumplido con tus tareas, reúne a tus fuerzas y preséntate ante el rey de los Gusanos en la necrópolis argoniana que está al norte. \n\nLa premura y la diligencia siempre son imperativas en estos asuntos, así que no remolonees en tus funciones.",
    ["Hail Mannimarco!\n\nYour humble servant reports that our experiments with the new soul flayers have been a resounding success. We disguised ourselves as merchants and brought one of the single-use flayers into a village near the Xul-Haj necropolis. The foolish lizards did not suspect a thing! We retreated to a safe distance to observe and activated the flayer. It performed as expected, sending out a burst of necrotic energy that killed everyone within the prescribed perimeter, sending their souls to the wraithforge. I will now return to collect the flayer for reconditioning.\n\nMay your work on the great rising swell our ranks with unstoppable undead warriors! May we gain an army of the dead from the depths of Xul-Haj!\n\nYour Servant,\nOverseer Bazgrum"] = "¡Salve, Mannimarco!\n\nTu humilde sirviente informa de que nuestros experimentos con los nuevos desolladores de almas han sido un éxito rotundo. Nos disfrazamos de mercaderes e introdujimos uno de los desolladores de un solo uso en una aldea cercana a la necrópolis de Xul-Haj. ¡Esos estúpidos lagartos no sospecharon nada! Nos retiramos a una distancia prudencial para observar y activamos el desollador. Funcionó como se esperaba, despidiendo un estallido de energía necrótica que mató a todo el mundo que se encontraba dentro del perímetro prescrito y envió sus almas a la Forja Espectral. Ahora regresaré para recoger el desollador y reacondicionarlo.\n\n¡Que tu obra en el gran alzamiento de no muertos llene nuestras filas de guerreros imparables! ¡Que consigamos un ejército de muertos en las profundidades de Xul-Haj!\n\nTu sirviente,\nSupervisor Bazgrum",
    ["Investigate the Village of Oozt-Tzel"] = "Investiga la aldea de Oozt-Tzel.",
    ["You mentioned the Void. I take it you're here on personal business and want to keep it that way?"] = "Has mencionado el Vacío. ¿Debo entender que has venido por asuntos privados y que prefieres mantener la discreción?",
    ["No. I'm sorry. I was reassigned to Gristmung Hold when they needed more help with the soul flayer experiments. I do not know where they sent Vanus after that.\n\nBut he wrote a note and slipped it to me. Asked me to get it to Gabrielle when I could."] = "No. Lo siento. Me reasignaron a la fortaleza Gristmung cuando necesitaron más ayuda con los experimentos de los desolladores de almas. No sé adónde se llevaron a Vano después de eso.\n\nPero escribió una nota y me la pasó disimuladamente. Me pidió que se la entregara a Gabrielle cuando pudiera.",
    ["Big, wretched siege weapon. Hits with the very hatred of Coldharbour. Blows against a ship are ruinous, and those against crew are fatal.\n\nNo idea what it would do to Velehk Sain and his lot. But Suraj would love to find out."] = "Un arma de asedio gigantesca y espeluznante. Ataca con todo el odio de Puerto Gélido. Contra un barco, sus golpes son devastadores; contra la tripulación, resultan letales.\n\nSuraj no sabe cómo afectaría a Velehk Sain y su gente, pero le encantaría averiguarlo.",
    ["Sithis worship has been a part of Argonian culture forever, though the Dread Father no longer features prominently in their day-to-day worship. \n\nBut here on Solstice, one warrior in each tribe, the death-dancer, still hews to the old ways."] = "La veneración a Sithis siempre ha formado parte de la cultura argoniana, aunque el Pavoroso Padre ya no figura prominentemente en sus oficios diarios.\n\nPero aquí, en Solsticio, cada tribu tiene un guerrero, el bailarín de la muerte, que sigue honrando las viejas tradiciones.",
    ["Kauldin studied under her. He was one of the apprentices she took under her wing and trained to be a marine.\n\nBut we saw her working with the cultists. She even struck down most of her apprentices. Kauldin's lucky to have survived."] = "Kauldin era su discípulo. Fue uno de los aprendices que tomó bajo su tutela; también estudió para ser soldado de marina.\n\nPero la vimos colaborar con los sectarios. Incluso mató a la mayoría de sus aprendices. Kauldin tuvo suerte de sobrevivir.",
    ["That tracks. We saw her carrying a staff and heading toward the gathering hall at the center of the lodge. When the cultist with her hurled a bolt of fire, I didn't think. I just leaped in front of Consewen.\n\nShe … she would do the same for me."] = "Eso tiene sentido. La vimos con un bastón dirigiéndose al salón de reuniones que hay en el centro de la logia. Cuando los sectarios que la acompañaban lanzaron un proyectil de fuego, no me lo pensé: salté delante de Consewen.\n\nElla... ella habría hecho lo mismo por mí.",
    ["Master Tanertor is alive! That's good to hear!\n\nPlease, activate the portal gate so I can get Latanwen to a healer in Sunport."] = "¡El maestro Tanertor está vivo! ¡Cómo me alegro de oírlo!\n\nPor favor, activa la entrada de portal para que lleve a Latanwen a Puerto Soleado y que pueda atenderla un sanador.",
    ["I do not like to answer such broad questions with a simple yes or no. First off, I am not Meridia. Her powers are not mine to bestow. But power can be transferred from one receptacle to another.\n\nThe Light of Meridia should be no different."] = "No me agrada responder categóricamente a preguntas tan generales. Para empezar, no soy Meridia; yo no otorgo sus poderes. Pese a todo, la energía puede transferirse de un receptáculo a otro.\n\nLa luz de Meridia no debería ser diferente.",
    ["I thought I heard shrieking. Didn't want to get my hopes up that it might have been her.\n\nPerhaps it's time I let those old bones go. If you're ready to move on, there's another favor I need to ask of you."] = "Me pareció escuchar unos chillidos. No quería hacerme ilusiones de que fuese ella.\n\nTal vez sea el momento de olvidarme de esos huesos. Si estás <<player{listo/lista}>> para pasar a otra cosa, hay otro favor que necesito pedirte.",
    ["There are two sides to every story. Long after our ancestors first sealed Mor Naril, they had to fight off Corelanya forays. Elven records of those troubled times reside in the library of the Sea and Sword Lodge.\n\nYou could seek your answers there."] = "Cada historia tiene dos versiones. Mucho tiempo después de que nuestros ancestros sellaran por primera vez Mor Naril, tuvieron que repeler las incursiones de los Corelanya. Los registros élficos de esas épocas turbulentas residen en la biblioteca de la Logia de Mar y Espada.\n\nPodrías buscar respuestas allí.",
    ["Hmm … very well. Allowing outsiders to have a look at the restricted parts of our collection is rather against the rules, but under these circumstances? I think it would be warranted.\n\nOne moment. I need to refer to our catalog."] = "Mmm... Muy bien. Permitir que los forasteros examinen las secciones restringidas de nuestra colección va en contra de las reglas, pero en estas circunstancias, creo que estaría justificado.\n\nUn momento, necesito consultar el catálogo.",
    ["<These crumbling notes are covered in fading Jel glyphs. In the margins, written in Tamrielic, are translation notes left by a Stone-Shaper some centuries ago.>\n\n<Translation> \"The war is won and yet I continue to toil away. Perhaps the others were right. If one wishes to know the color of obsession, you need only look to my scales. At my aching, calloused claws shaped to the handles of my tools. But I do not work without purpose.\n\n\"I see a new hunger growing in the eyes of our leaders. They see my guardians not as protectors, but as weapons. Tools for a war beyond our shores. This is not why I built them. I will now spend my final years locking them away, along with their control stone. The wonders of this temple, once a testament to our courage, are now a trap for those seeking war in times of peace.\"\n\n* * *\n<Translator's Note> So the vault I glimpsed at the temple's center holds not viridian life, but the forms which were shaped from it. The voskrona. It is strange, translating the words of an Argonian as ancient as I feel. How I empathize with his aches as I see a slow, growing harshness to his glyphs. An unevenness that reveals a petrified shoulder. A locked wrist. Ailments that I too massage between quill strokes.\n\nLife-Carver Tzinik-Muz, we are egg-kin more than I could have realized. I do not seek your guardians as tools of war. In truth, I wished for the secrets of their design so I too could shape life from stone. Hubris is the color of my scales.\n\nI wish I could see these protectors first hand, but this old stone-shaper can proceed no farther into these old ruins. I leave my notes to any egg-kin who may follow in my steps. If you seek out Tzinik-Muz's vault, and the voskrona guardians' control stone, you must first release the three counterweights and face the temple's pendulums with courage.\n\nStone-Shaper Jazeez"] = "<Estas notas deterioradas están cubiertas de glifos jel desdibujados. Los márgenes presentan anotaciones de traducción escritas en tamriélico por un moldeador de piedra siglos atrás.>\n\n<Traducción> «Aunque la guerra está ganada, sigo trabajando sin descanso. Quizá los demás tenían razón. Si uno desea averiguar de qué color es la obsesión, basta con contemplar mis escamas; mis garras doloridas y callosas, moldeadas por el manejo de mis herramientas. Sin embargo, no trabajo por amor al arte».\n\n«Observo una nueva ambición crecer en las miradas de nuestros líderes. No ven a mis guardianes como protectores, sino como armas; instrumentos para librar una guerra más allá de nuestras costas. Eso no es lo que me llevó a construirlos. Ahora, pasaré los años que me quedan poniéndolos a buen recaudo, junto con su piedra de control. Las maravillas de este templo, otrora símbolos de nuestro coraje, se han convertido en una trampa para quienes buscan la guerra en tiempos de paz».\n\n* * *\n<Nota del traductor> Así que la cámara que vi en el centro del templo no contiene vida viridiana, sino las formas que se moldearon con ella: los voskrona. Resulta extraño traducir las palabras de un argoniano tan anciano como yo me siento. Cómo empatizo con sus dolores a medida que identifico una brusquedad que, poco a poco, va agudizándose en sus glifos. Una descompensación que denota un hombro petrificado; una muñeca rígida. Dolencias que yo también atiendo con masajes entre cada trazo de pluma.\n\nEscultor de vida Tzinik-Muz, somos hermanos de nidada más cercanos de lo que podría haber imaginado. No pretendo usar tus guardianes como instrumentos de guerra. La verdad es que anhelaba los secretos de su diseño para esculpir también vida a partir de la piedra. La soberbia es el color de mis escamas.\n\nOjalá pudiese ver con mis propios ojos a esos protectores, pero este viejo moldeador de piedra no es capaz de avanzar más en estas ruinas antiguas. Dejo mis anotaciones para cualquier hermano o hermana de nidada que siga mis pasos. Si buscáis la cámara de Tzinik-Muz y la piedra de control de los guardianes voskrona, antes debéis liberar los tres contrapesos y enfrentaros con valentía a los péndulos del templo.\n\nMoldeador de piedra Jazeez",
    ["I couldn't believe it when I heard that this place had ended up in Nirn. I convinced Sirilonwe that a research trip would provide a lot of information on vampires. Things the Mages Guild can use to combat any who posed a danger. This approach worked as I knew it would.\n\n* * *\nThe trip was uneventful and we made camp. I feel a strange sense of purpose? Energy? I am close. I know it. \nWe met another mage, Ormard. He has worked on a vampire compendium for decades, so it's no surprise that he knew of this place. He's a pleasant Nord fellow and even Sirilonwe warmed to him. \n\nOrmard and I have compared notes. His interest seems purely academic and he is eager to get into the place. Sirilonwe is still making some plans, not wanting to rush headlong into danger as she says. Ormard has been generous with the information he has on the Hall. It has sealed doors, different sections. Ormard says there are unique keys or tokens of some sort to open them. \n\n* * *\nOrmard and I decided to do an initial survey into the Hall. I confessed that my real interest was not so much the vampire denizens, but rather the Daedric artifacts rumored to be held within, and that I wanted to confirm that and maybe even bring one back to do my own research. I said Sirilonwe had strong opinions about what she calls relic hunting so I have not told her my true purpose. Ormard understood. He then confessed he found a break in the foundations! A small cave south of our camp. It will allow us to slip quietly into the place, as the main doors appear to be inaccessible after the place fell out of Coldharbour. \n\nWe're doing it. I am close. My heart is racing. Sirilonwe will be furious, but I am sure I can talk her around."] = "Cuando me contaron que este lugar había acabado en Nirn, no me lo podía creer. Convencí a Sirilonwe de que una expedición de investigación nos proporcionaría mucha información sobre los vampiros, datos que el gremio de magos podría usar para combatir a cualquiera que representara una amenaza. Este enfoque funcionó, como sabía que haría.\n\n* * *\nNo hemos tenido incidentes en el viaje y hemos acampado. Siento una extraña sensación de... ¿propósito? ¿Energía? Estoy cerca, lo sé. \nHemos conocido a otro mago llamado Ormard. Lleva décadas trabajando en un compendio vampírico, por lo que no es de extrañar que conozca este lugar. Es un nórdico simpático; incluso a Sirilonwe le ha caído bien. \n\nHe estado comparando notas con Ormard. Su interés parece exclusivamente académico y está deseando acceder al lugar. Sirilonwe sigue haciendo planes. No quiere lanzarse de cabeza al peligro, como ella dice. Ormard ha sido generoso con la información que posee sobre el salón: las puertas están selladas y cuenta con diferentes secciones. Ormard asegura que hay unas llaves únicas o unos símbolos de alguna clase que sirven para abrirlos. \n\n* * *\nOrmard y yo decidimos llevar a cabo una primera prospección en el salón. Le confesé que mi interés no radicaba tanto en los vampiros que lo habitaban como en los artefactos daédricos que supuestamente albergaba en su interior, que quería confirmarlo y, tal vez, llevarme uno para investigarlo por mi cuenta. Le dije que Sirilonwe no veía con buenos ojos lo que ella llamaba «caza de reliquias» y que por eso mismo no le había revelado mi verdadero propósito. Ormard lo entendió... ¡y confesó que había encontrado una grieta en los cimientos! Hay una pequeña cueva al sur de nuestro campamento. Nos permitirá colarnos sin llamar la atención, ya que las puertas principales parecen inaccesibles desde que el recinto cayó de Puerto Gélido. \n\nVamos a hacerlo. Estoy cerca. Mi corazón retumba. Sirilonwe se pondrá furiosa, pero estoy seguro de que lograré calmarla.",
    ["The Vos-Toh stone tablets offer a glimpse into Argonian death-dancers' beliefs in ancient times. I find them quite inspiring. They deserve extensive study. There are far more than just these simple words beneath the surface of the carefully carved glyphs.\n\n* * *\nVos-Toh of Song\n\nHail Sithis, the nothing of the Outer Darkness. No gentle truths placate fear. Embrace fear, for it is the song of the blood. We raise our voices to speak the words of the Void, the artistry of the Void, the truth of the Void.\n\n* * *\nVos-Toh of Dance\n\nHail Sithis, the serpent of chaos. Constantly moving. Never still. So we dance a ceaseless promenade. To one day slide and step and bounce joyously into the Void. To enact his will with perfect clarity and one day dance beside the Night Lord himself.\n\n* * *\nVos-Toh of Death\n\nHail Sithis, the ever-changing. What is consumed is restored. This is why we die. To one day soar beyond the reach of sun and stars, to enter the space between. To honor his will. To destroy what was and create what will be."] = "Las tablillas de piedra vos-toh permiten vislumbrar las creencias antiguas de los Bailarines de la Muerte argonianos. Me resultan bastante inspiradoras. Merecen un estudio pormenorizado. Bajo la superficie de los glifos cuidadosamente tallados, hay mucho más que unas simples palabras.\n\n* * *\nVos-toh de la canción\n\nSalve, Sithis, la nada de la oscuridad exterior. Ninguna verdad amable aplaca el miedo. Abrazad el miedo, pues es la canción de la sangre. Alzamos nuestras voces para pronunciar las palabras del Vacío, el arte del Vacío, la verdad de Vacío.\n\n* * *\nVos-toh del baile\n\nSalve, Sithis, la Serpiente del Caos. En constante movimiento, nunca quieta. Por eso bailamos una danza eterna: para, algún día, poder deslizarnos, dar pasos y saltar alegremente hacia el Vacío; para cumplir su voluntad con perfecta claridad y, algún día, bailar junto al mismísimo Señor de la Noche.\n\n* * *\nVos-toh de la muerte\n\nSalve, Sithis, el siempre cambiante. Lo consumido se restaura. Por eso morimos: para, algún día, ascender más allá del alcance del Sol y las estrellas; para acceder al espacio intermedio; para honrar su voluntad; para destruir lo que fue y crear lo que será.",
    ["Tell me then, this Mani-Kai. I see a brittle thing, fresh from her egg. Eager as the lichen that grows wide without first placing roots. Do you trust her? Can she really hear the Hist?"] = "Entonces, dime una cosa: esa tal Mani-Kai, a la que veo tan frágil, como recién salida del cascarón, es tan ansiosa como el liquen que se expande sin echar raíces primero. ¿Confías en ella? ¿De verdad oye al hist?",
    ["How lucky are you to have walked through the mud alongside my teacher. You know then that the chimes I carry will help me interpret this tree's song. I only hope it will be enough to prove to these villagers that we are here to help."] = "Qué suerte tienes de haber caminado por el barro junto a mi maestro. Entonces, sabrás que las campanillas que llevo me ayudarán a interpretar la canción de este árbol. Solo espero que baste para demostrarles a estos aldeanos que estamos aquí para ayudar.",
    ["There's a letter over there from Adrolir. It's addressed to you."] = "En la arena hay una carta de Adrolir. Lleva tu nombre.",
    ["Need to get more information from Ormard on these doors. Such elaborate mechanisms. Not mechanical. Not wholly magical. He said that he has a way to get past them, thanks to his various partners within the hall. Well, not partners, exactly. He continues to be a bit cagey with his information thus far.\n\nI hope Sirilonwe manages to catch up eventually. She should be here to write down all my observations."] = "Necesito que Ormard me dé más información sobre estas puertas. Qué mecanismos tan elaborados presentan. No son mecánicas, pero tampoco totalmente mágicas. Dice que puede cruzarlas gracias a los diversos socios que tiene dentro del salón. Bueno, no son exactamente «socios», pero sigue mostrándose algo esquivo con el tema.\n\nEspero que Sirilonwe consiga alcanzarnos en algún momento. Debería estar aquí para anotar todas mis observaciones.",
    ["If the journals spoke true, their creators intended for them to act as defenders of their people. Let us hope that we have given the egg-kin of Xor-Hist the edge they need to face the necromancers."] = "Si los diarios decían la verdad, sus creadores pretendían que actuaran como defensores de su tribu. Esperemos haber dotado a Xor-Hist de la fuerza necesaria para enfrentarse a los nigromantes.",
    ["Here as in Nirn? A whirlpool opened up on the azure seas. Captain One-Eye cackled and sailed us right in. Somehow she knew it would get us out of Coldharbour.\n\nNo one knew it would drop us from the sky. Or that Velehk Sain would dare to follow."] = "Cuando dices aquí, ¿te refieres a Nirn? Se abrió un remolino en los mares cerúleos. La capitana Ojo Único soltó una carcajada y nos llevó directamente hacia él. De algún modo, sabía que nos sacaría de Puerto Gélido.\n\nNadie se esperaba que nos hiciera caer del cielo. Ni que Velehk Sain se atreviera a seguirnos.",
    ["by Midconjuror Mirmal of the College of Rituals\n\nFew of Sunport's folk venture across the Solstice Range to visit the eastern half of our fair island. Yet this was not always the case. When House Corelanya first settled on these shores, our ancestors looked beyond the mountains and saw a land ripe for settlement. The fact that the Stone-Nest Argonians already lived there did little to deter the interest of proud kinlords and kinladies who desired a realm wide enough to suit their ambitions.\n\nWhen Kinlord Orlemar came to power in 1E 1017, he decided to act upon those ambitions. During his reign, vast tracts of land in eastern Solstice were parceled out to powerful nobles to settle or exploit as they wished. Yet no one seems to have informed the Stone-Nests about the arrangement. Centuries of strife between Elf and Argonian followed from the haughty kinlord's dealings.\n\nNaturally, Orlemar did not forget himself when handing out parcels of eastern Solstice. The kinlord claimed a magnificent estate in the northern part of the island, and named it Vaedinhill. There he commissioned the building of a great manor-house to serve as his summer palace, a luxurious retreat from the cares of the cares of the throne.\n\nThe cost of building Vaedinhill Manor nearly bankrupted the realm. Constructing such an extravagant palace in the wilds of eastern Solstice, far from the resources and workforce of Sunport, proved expensive indeed. But in 1E 1107, Kinlord Orlemar's palace was finally completed, a vision of fair Summerset amid a virgin wilderness. It was not to last.\n\nArgonian resistance to Kinlord Orlemar's policies was growing. While the kinlord enjoyed his palace for a time, travel to and from Vaedinhill became dangerous. Bands of Stone-Nest warriors began to shadow, and sometimes attack, travelers and wagons on the road to Vaedinhill. Orlemar found it increasingly difficult to maintain his court in the east. He did not visit the manor at all in the last ten years of his life, although he was laid to rest there.\n\nWhen open fighting broke out in 1E 1172, Stone-Nest warriors burned down Vaedinhill. During the troubled years that followed, Orlemar's successors could find neither the funds nor the forces needed to rebuild Vaedinhill. By the time Kinlady Torinwe concluded the Peace of Xor-Hist, House Corelanya had no interest in maintaining grand estates east of the mountains.\n\nOne can still visit the ruins of Vaedinhill to this day. Crumbling walls of white stone and weed-choked courtyards attest to the magnificence of Kinlord Orlemar's vision—and his folly."] = "Del invocador medio Mirmal, del Colegio de Rituales\n\nPocos habitantes de Puerto Soleado se aventuran a cruzar la cordillera de Solsticio para visitar la mitad oriental de nuestra hermosa isla, pero esto no ha sido siempre así. Cuando la Casa Corelanya se estableció en estas costas, nuestros antepasados miraron más allá de las montañas y vieron una tierra que esperaba a ser colonizada. El hecho de que los argonianos Nido Pétreo ya vivieran allí no disuadió a los orgullosos jerarcas de la familia, que deseaban un reino lo bastante amplio como para satisfacer sus ambiciones.\n\nAl asumir el poder en el 1017 de la PE, el jerarca Orlemar decidió hacer realidad estas ambiciones. Durante su reinado, entregó vastas extensiones de terreno de Solsticio Oriental a nobles poderosos para que las colonizaran o las explotaran a su antojo, pero nadie informó a los Nido Pétreo del acuerdo. Los tratos del altivo jerarca dieron paso a siglos de conflicto entre elfos y argonianos.\n\nPor supuesto, Orlemar se incluyó en el reparto de parcelas de Solsticio Oriental. Reclamó una fabulosa hacienda situada en el norte de la isla, que llamó Vaedinhill, y en ella ordenó construir una gran mansión que le sirviera como palacio de verano, un lujoso refugio alejado de las preocupaciones del trono.\n\nLa mansión de Vaedinhill estuvo a punto de dejar en bancarrota al reino. Construir un palacio tan extravagante en las tierras salvajes de Solsticio Oriental, lejos de los recursos y la mano de obra de Puerto Soleado, tuvo un coste desorbitado. Aun así, el palacio del jerarca Orlemar abrió sus puertas en el año 1107 de la PE, ofreciendo una hermosa visión de Estivalia en plena naturaleza virgen. Sin embargo, no duró demasiado.\n\nLa resistencia argoniana a las políticas del jerarca Orlemar iba en aumento. Este pudo disfrutar de su palacio durante un tiempo, pero el viaje de ida y vuelta se tornó peligroso. Las bandas de guerreros Nido Pétreo empezaron a seguir e incluso atacar a los viajeros y carromatos que se dirigían a la mansión. Esto hizo que a Orlemar le resultará cada vez más difícil mantener su corte en oriente. Durante sus últimos diez años de vida, no volvió a poner un pie en Vaedinhill, aunque fue enterrado allí.\n\nAl estallar la guerra en el 1172 de la PE, los guerreros Nido Pétreo prendieron fuego a Vaedinhill. Durante los turbulentos años que siguieron, los sucesores de Orlemar no lograron reunir los fondos ni las fuerzas necesarios para reconstruir la mansión y, para cuando la jerarca Torinwe firmó el Tratado de Paz de Xor-Hist, la Casa Corelanya ya no estaba interesada en mantener grandes haciendas al este de las montañas.\n\nTodavía se pueden visitar las ruinas de Vaedinhill. Las paredes derruidas de piedra blanca y los patios cubiertos de maleza son un testimonio de la magnificencia de la visión del jerarca Orlemar... y de su locura.",
    ["Scrounged up some paper and managed to make a ship's log. I don't rightly know what day it is and haven't for some time. No sense marking the days, but figure maintaining a record might keep me level.\n\nWe're about done cobbling together our ship. Decided the Bonnie Spriggan suits just fine as a name. Most of her salvaged pieces are from that wreck anyhow, after the Era burnt down. Should have left more to guard her, I suppose, but circumstances couldn't be helped. \n\nCrew didn't much like that ship anyway, on account of it belonging to the admiral. Trying not to let the loss eat me up inside. Wood's not natural to Coldharbour, so naming her the Bonnie Spriggan seems aspirational in a way. \n\n* * *\nHaven't even set sail, and we already found a stowaway. A wrinkled soul-shriven tucked up among our supply crates. Been living there for some time by the looks of it. Calls herself Argenta and she speaks like we've just woken her from a nightmare. Going on about some Wailing Prison, about needing to escape. Don't know if she can hold herself together enough to even take orders, but she's part of the crew. Any with aims to escape this wretched plane are welcome aboard the Bonnie Spriggan. All the better if you can pull your weight, but I've got a legion of Lost Fleet sailors behind me who can fill in for those that can't. \n\n* * *\nFound others seeking escape. Surprised at how many were absconded here or simply left behind. Even more surprised that they managed to survive this long. One, a strapping Orc called Khag, brought warning of some pirate king sent to retrieve the Crown of Bones from me. \n\nThat got a fire lit under us, I'll tell you. We made final repairs and cast off on the azure sea. Strange thing to sail on, but I've just about got a handle on it. The Spriggan's unwieldy, but she'll hold. I've got my shaman's tricks to make sure of it.\n\n* * *\nTurns out Argie, Argenta, can cook. Crew says the food's not bad, either. Argie gets a bit stabby with the still-wriggling ingredients we manage to fish up from the plasm, but we keep an eye on her. Didn't much think about how to feed a mortal crew, I'll admit. Glad we decided to keep her.\n\n* * *\nKeep picking up stragglers, mortals trapped in Coldharbour who became caught in its web one way or another. Not an honest-born pirate among the lot of them, but they're learning to sail all the same. Learning to outwit first and only fight as a last resort. That's how we stay alive. \n\n* * *\nFinally, this supposed pirate captain Khag warned us about. Captain Velehk Sain. Caught up to us at long last. \n\nLost a good number of our crew. Lost Fleet skeletons, mostly. But not all. Managed to outfox him with some Black Marsh magic at a crucial moment. That made him mad.\n\nBlame myself for this. For underestimating this captain hunting us. Lost him for now, but I can see he's sly enough and brutal in spades. He'll find his way back to us. Daedra always do. \n\n* * *\nCame in a circle, back to our makeshift dockyard and scavenged up some poor sap called Kuxali. He'd put a crew together to come looking for me. Me! Got caught in the same whirlpool that led me to this Sithis-damned fate. Well, his crew are all dead now. So that's one thing we have in common.\n\nFool says he looked up to me as a young hatchling. Not something I asked for, so not something I need or want to feel guilty about. But want and will sometimes pull against each other. \n\nBeen a miserable stretch as we try to keep ahead of Captain Sain, and I guess Kuxalis's lost his shine on me. \n\nSo there's another thing we have in common.\n\n* * *\nAnother brush with Captain Sain. That Harvester of his managed to slither on the deck of the Spriggan on what we thought was a quiet night. Crewman Salvus rang the bell as warning, and it had some strange effect on her. Looked closer and found ancient runes engraved on the inside. Some sort of enchantment from the original owners among the Lost Fleet, I figure. Managed to drive her off in all her frenzy, and she only dragged two into the plasm. Thank Sithis for that.\n\nWhen next our ships met, Khag made some daring maneuvers and managed to break aboard the Caterwaul to steal supplies. And found a cat! A cat aboard the Caterwaul. Damn his soft heart. \n\n* * *\nTurning the tide where Captain Sain is concerned. Losing fewer each brush with him. Din learning to steer and avoid hits from those wretched Teeth. \n\nCat turned out to be a sly little Alfiq named Suraj. Gets along well with everyone, even surly Murph, even better than Din. So that time, we even gained one for the two we lost.\n\n* * *\nTwo among our crew came to see me independently about customs of captains performing marriages at sea. Not a custom I'd heard of in my corner of Black Marsh, said I, but I'd do as they liked.\n\nStill not sure if they were talking about each other, but I'll keep it to meself until they work it out.\n\n* * *\nCrew's stronger than ever. Battened down into some real pirates. But I don't know how long we can keep limping along like this. So few of our Lost Fleet remain after taking hits for our mortal crew. The hits we take after this feel like they'll count for more. \n\nBeen praying to Sithis to send something our way. Anything from a rogue wave to a bottomless plummet off a cliff would be welcome at this point.\n\nThought this log had more pages. Strange. Wonder where they went."] = "He conseguido papel y he logrado elaborar un cuaderno de bitácora. No sé con exactitud qué día es y llevo tiempo sin saberlo. No tiene sentido anotar los días, pero imagino que llevar un registro mantendrá mi mente equilibrada.\n\nCasi hemos terminado de ensamblar nuestro barco. He decidido que «Linda Spriggan» es un nombre que le pega mucho. La mayoría de sus piezas proceden de ese naufragio, después de que el Era Dorada ardiese. Debería haber dejado más para protegerlo, supongo, pero las circunstancias así lo exigían. \n\nA la tripulación no le gustaba mucho ese barco de todas formas debido a que pertenecía al almirante. Intento que la pérdida no me carcoma por dentro. La madera no existe de forma natural en Puerto Gélido, así que llamarlo el «Linda Spriggan» tiene algo de esperanzador. \n\n* * *\nNi siquiera hemos zarpado y ya tenemos una polizona. Un alma condenada, arrugada y acurrucada entre nuestras cajas de provisiones. Parece que lleva bastante tiempo viviendo ahí. Dice llamarse Argenta y habla como si acabara de despertarse de una pesadilla. No deja de parlotear sobre algo llamado la «Prisión de los Lamentos» y de que debe escapar. Ni siquiera sé si recobrará la compostura suficiente para recibir órdenes, pero ya es parte de nuestra tripulación. Cualquiera que pretenda escapar de este maldito plano es bienvenido a bordo del Linda Spriggan. Mucho mejor si puede arrimar el hombro, pero tengo a mi mando una legión de marineros de la Flota Perdida que pueden hacer el trabajo de quienes son incapaces de colaborar. \n\n* * *\nHe encontrado a otros que quieren escapar. Me sorprende cuántos se escondieron en este plano o simplemente quedaron atrás. Y me sorprende aún más que hayan logrado sobrevivir tanto tiempo. Uno de ellos, un fornido orco llamado Khag, me ha advertido sobre un rey pirata al que han enviado para quitarme la corona de huesos. \n\nEsa noticia ha sido como una brasa bajo los pies, la verdad. Hemos terminado los últimas reparaciones y hemos zarpado. Es raro navegar en el mar cerúleo, pero ya le he pillado el tranquillo. Aunque cuesta manejar el Spriggan, aguantará. Tengo mis trucos de chamana para asegurarme de ello.\n\n* * *\nResulta que Argie, Argenta, sabe cocinar. Y la tripulación dice que su comida no está mal. Argie se pone a apuñalar como una loca los ingredientes vivos que pescamos del plasma, pero le estamos echando un ojo. Reconozco que no había pensado en cómo alimentar a una tripulación mortal, así que me alegro de haberla aceptado a bordo.\n\n* * *\nSeguimos recogiendo rezagados, mortales que quedaron atrapados en Puerto Gélido de una forma u otra. Ni un pirata nato entre ellos, pero están aprendiendo a navegar igualmente. A burlar al enemigo con ingenio y a luchar solo como último recurso. Así es como seguimos con vida. \n\n* * *\nPor fin nos ha alcanzado el presunto capitán pirata del que nos advirtió Khag: el capitán Velehk Sain. \n\nNuestra tripulación ha sufrido muchas bajas, sobre todo de esqueletos de la Flota Perdida, pero no los perdimos a todos. Hemos logrado burlar al capitán con magia de la Ciénaga Negra; se ha puesto furioso.\n\nEs culpa mía por haber infravalorado a nuestro perseguidor. Por ahora, le hemos dado esquinazo, pero me he dado cuenta de que es lo bastante astuto y sobradamente cruel. Encontrará la forma de alcanzarnos. Los daedra siempre la encuentran. \n\n* * *\nHemos vuelto al principio del círculo, a nuestro astillero improvisado, y hemos rescatado a un pobre idiota llamado Kuxali. Había juntado una tripulación para ir buscarme. ¡A mí! Quedó atrapado en el mismo torbellino que me condujo a este destino maldito por Sithis. Bueno, ahora toda su tripulación está muerta, así que ya tenemos una cosa en común.\n\nEl idiota dice admirarme desde que salió del cascarón. No es algo que yo haya pedido, así que ni necesito ni quiero sentirme culpable por ello, pero deseo y voluntad a veces se contradicen. \n\nHemos tenido un trecho muy arduo tratando de mantener la distancia con el capitán Sain y supongo que Kuxali ya no tiene un concepto tan alto de mí. \n\nAsí que tenemos algo más en común.\n\n* * *\nOtro encontronazo con el capitán Sain. Su segadora logró deslizarse por la cubierta del Spriggan durante lo que pensábamos que sería una noche tranquila. El tripulante Salvo tocó la campana para advertirnos y eso tuvo un extraño efecto en ella. Al examinarla de cerca, advertimos unas runas antiguas grabadas en su interior. Supongo que se trata de algún tipo de encantamiento de los propietarios originales de la Flota Perdida. Conseguimos echarla en pleno frenesí y solo consiguió arrastrar a dos al plasma. Alabado sea Sithis.\n\nEn cuanto nuestros barcos se encontraron, Khag realizó unas maniobras temerarias y logró abordar el Alarido para robar provisiones. ¡Y también encontró un gato! Un gato a bordo del Alarido. Maldigo su corazón de oro. \n\n* * *\nEstamos cambiando las tornas en lo que respecta al capitán Sain. En cada encontronazo con él, perdemos menos tripulantes. Din está aprendiendo a virar y a esquivar los disparos de esos malditos dientes. \n\nEl gato ha resultado ser un astuto alfiq llamado Suraj. Se lleva bien con todo el mundo, incluso con el hosco de Murph, incluso mejor que Din. Así que, esa vez, incluso ganamos un tripulante por los dos que perdimos.\n\n* * *\nDos miembros de la tripulación han acudido a mí, cada cual por su lado, para preguntarme por la costumbre de que el capitán oficie bodas en alta mar. Les he dicho que no es una costumbre de la que haya oído hablar en mi rincón de la Ciénaga Negra, pero que estoy dispuesta a hacerlo.\n\nNo sé si estaban hablando el uno de la otra, pero me lo callaré hasta que se aclaren entre sí.\n\n* * *\nLos tripulantes son más fuertes que nunca. Se han curtido hasta volverse unos auténticos piratas, pero no sé cuánto tiempo podremos aguantar dando tumbos así. Quedan muy pocos esqueletos de la Flota Perdida tras recibir los disparos dirigidos a nuestra tripulación mortal. Sentiremos mucho más las bajas que suframos a partir de ahora. \n\nHe estado rezando a Sithis para que envíe algo que nos ayude. Cualquier cosa, desde una ola gigante hasta una caída por un abismo sin fondo, sería bienvenida llegados a este punto.\n\nCreía que este cuaderno de bitácora tenía más páginas. Qué raro. Me pregunto dónde estarán.",
    ["Well, that's an image I didn't need in my head. But I get it. Darien Gautier is not a quitter, and I'm not going to start now. I have to push on. Make my life and my battles worth the sacrifice of others. I have to.\n\nLet's rejoin the others."] = "Bueno, eso es algo que no necesitaba imaginarme. Pero lo entiendo. Darien Gautier no se echa atrás y no va a hacerlo ahora. Tengo que seguir adelante; hacer que mis batallas merezcan que otros se sacrifiquen. Es mi deber.\n\nVolvamos con los demás.",
    ["Her Kinlady Torinwe of Corelanya, regarding with her favor the native rulers and tribes of Solstice and anxious to put to rest the strife between all the inhabitants of the island, wishes to secure for all impacted by the unrest peace, security, and good will between Elves and Argonians, which has been thus far exacerbated by the aforementioned conflict. \n\nTo this end she, alongside Tuintirrimo of the Corelanyan Guard and Pamaldawe of the Collegium, invite Mahei-Gei, representative for the Tide-Born of the western shores, and Tlekeus, speaking for the Stone-Nest of the eastern reaches, to concur upon the following articles and conditions. \n\nARTICLE THE FIRST\nAs long as all spoken-for inhabitants of Solstice adhere to the articles laid out in this document, they will lay down their arms against one another and vow to refrain from taking any hostile actions regarding ancestral or recent grievances. \n\nARTICLE THE SECOND\nAs set forth by this assembled congregation, the territories belonging to the Corelanya, Stone-Nest, and Tide-Born are hereby recognized as the sovereign land of the peoples thereof. Corelanya and Argonian alike agree not to encroach on the others' lands or impede them from crossing from one territory to another. Henceforth, no permanent dwellings shall be constructed in another's territory without express and written permission.\n\nARTICLE THE THIRD\nIn times when Solstice is threatened, we will temporarily waive the previous articles for the sake of mutual defense. \n\nWe signatories and assembled attendants, having been made fully aware of the provisions of this treaty, accept and enter into the full spirit of the stated agreement. \n\nCompleted at Xor-Hist in the year 1244 of the First Era."] = "La jerarca Torinwe de los Corelanya, movida por su aprecio a las tribus y los gobernantes autóctonos de Solsticio, y ansiosa por solucionar el conflicto entre todos los habitantes de la isla, desea asegurar, en favor de todos los afectados por la disputa, la paz, la seguridad y la buena voluntad entre elfos y argonianos, hasta ahora socavadas por susodicho conflicto. \n\nA tal fin, acompañada de Tuintirrimo, de la guardia de los Corelanya, y Pamaldawe, de la Collegium Praxis, insta a Mahei-Gei, representante de los Sangre Acuosa en las costas occidentales, y a Tlekeus, portavoz de los Nido Pétreo en los confines orientales, a acordar los siguientes artículos y condiciones. \n\nARTÍCULO PRIMERO\nSiempre y cuando todos los habitantes representados de Solsticio cumplan con los artículos estipulados en este documento, depondrán las armas y jurarán abstenerse de emprender cualquier acto hostil en relación con agravios antiguos o recientes. \n\nARTÍCULO SEGUNDO\nPor la presente, tal y como dispone la congregación aquí reunida, los territorios pertenecientes a los Corelanya, los Nido Pétreo y los Sangre Acuosa quedan reconocidos como tierras soberanas de sus respectivas gentes. Tanto los Corelanya como los argonianos acuerdan no invadir las tierras ajenas ni impedirse el paso de un territorio a otro. De ahora en adelante, no se construirán viviendas permanentes en territorio ajeno sin autorización expresa y por escrito.\n\nARTÍCULO TERCERO\nEn caso de que Solsticio se hallare en peligro, los artículos anteriores quedarían provisionalmente sin efecto en pos de la defensa mutua. \n\nLos signatarios y asistentes aquí reunidos, habiendo tomado pleno conocimiento de las disposiciones de este tratado, reconocen y ratifican plenamente el acuerdo estipulado. \n\nRefrendado en Xor-Hist en el año 1244 de la Primera Era.",
    ["Long ago, my people were called upon to battle a terrible evil in Mor Naril. They made the voskrona for that purpose. Down through the ages, evil has returned from time to time. Most recently when the Corelanyas came to plunder Mor Naril's secrets."] = "En tiempos remotos, mi tribu fue convocada para luchar contra un mal terrible en Mor Naril. Crearon a los voskrona para ese propósito. Con el paso de los siglos, ese mal ha regresado una y otra vez. La última fue cuando los Corelanya vinieron para robar los secretos de Mor Naril.",
    ["It's not about falling. It's about getting up once again. And I know you can do that."] = "La cuestión no es caerse, sino volver a levantarse después. Y sé que puedes hacerlo.",
    ["Has anyone ever told you Stone-Nests that your heads are as hard as rocks?"] = "¿Te han dicho alguna vez que los Nido Pétreo tenéis la cabeza más dura que una roca?",
    ["Of course. A greataxe. A maul. A greatsword. A spear. A quarterstaff."] = "Por supuesto. Con una gran hacha, con un mazo, con un mandoble, con una lanza, con una pica...",
    ["\"Release them, vile fiend!\"\n\nThere it is! Such strength. Such power! I feel like I could punch a horse! Has this always been within me? For better or worse, you've helped unleash a beast. Thank you."] = "«¡Deja que se marche, sabandija miserable!».\n\n¡Eso es! ¡Qué fuerza! ¡Qué intensidad! ¡Me siento capaz de tumbar a un caballo de un puñetazo! ¿Tenía toda esta fuerza dentro? Para bien o para mal, has liberado una bestia. Gracias.",
    ["Return to Lanullin"] = "Vuelve con Lanullin",
    ["Deliver Baked Potato to Nenilon"] = "Entrégale una patata asada a Nenilon",
    ["So you readily admit you were manipulated? How easily a little stone bends to the whims of wind and rain. You've wasted enough of my time. As the village's death-dancer, it is my duty to strike you down. Ready yourself."] = "¿Así que admites que te ha manipulado? Con qué facilidad se doblega una piedrecilla a los caprichos de la lluvia y el viento... Ya me has hecho perder mucho tiempo. Como bailarín de la muerte de esta aldea, es mi deber abatirte. Ponte en guardia.",
    ["Deliver Banana Surprise to Geraldrim"] = "Entrégale una sorpresa bananera a Geraldrim",
    ["Deliver Carrot Soup to Teliwe"] = "Entrégale una sopa de zanahoria a Teliwe",
    ["Craft Banana Surprise"] = "Prepara una sorpresa bananera",
    ["Craft Carrot Soup"] = "Prepara una sopa de zanahoria",
    ["Craft Baked Potato"] = "Prepara una patata asada",
    ["You need to gain Prince Naemon's trust, too. I would do it myself, but he knows me too well. \n\nHis chambers are through the door to our left. Now that I'm in the citadel, I can help with whatever task he gives you. So find me when you're done."] = "También necesitas ganarte la confianza del príncipe Naemon. Lo haría yo misma, pero me conoce demasiado bien.\n\nSus aposentos están al otro lado de la puerta que hay a nuestra izquierda. Ahora que estoy en la ciudadela, puedo ayudarte con las tareas que te encargue, así que ven a verme cuando hayas terminado.",
    ["And how funny is it that the roots of their Hist tree forced them to abandon this temple. There is poetry to that, I am certain of it, but I have not an artist's patience."] = "Y qué gracioso es que las raíces de su árbol del hist los obligaran a abandonar este templo. Es pura poesía, no cabe duda, pero yo no tengo paciencia de artista para capturarla.",
    ["You must be Sirilonwe. The scout Mihnassi told me you lost your friend near the Ashbound Hall."] = "Tú debes de ser Sirilonwe. La exploradora Mihnassi me dijo que habías perdido a tu amigo cerca del Salón Cinéreo.",
    ["Soon after the Wall fell, a mage named Ormard came to us. He'd seen the Hall and offered to guide us here. Now I wake up and they're both gone. Come, I'll pay you to escort me while I find Terinvel. The vampires may no longer be securely locked away."] = "Poco después de que cayera el muro, un mago llamado Ormard se nos acercó. Había visto el salón y se ofreció a guiarnos hasta aquí. Cuando me he despertado, los dos habían desaparecido. Acompáñame y te pagaré por escoltarme mientras busco a Terinvel. Puede que los vampiros ya no estén encerrados.",
    ["As I understand it, the Stone-Nest Argonians had numerous encounters with the Daedra when they first arrived on the island. After capturing and guarding the relic for generations, they gave it to us to protect. We must retrieve it."] = "Por lo que sé, los argonianos Nido Pétreo tuvieron muchos enfrentamientos con los daedra cuando llegaron a la isla. Tras capturar la reliquia y guardarla durante generaciones, nos la entregaron para que la protegiéramos. Debemos recuperarla.",
    ["Return to Tibarr"] = "Vuelve con Tibarr",
    ["Give the Coin to the Beggar"] = "Entrégale la moneda al mendigo",
    ["Steal a Coin from the Dragon's Hoard"] = "Roba una moneda del tesoro del dragón",
    ["There are low-ranking Worm Cultists everywhere, but few leaders or major outposts besides Gristmung Hold. Raz thinks most of the important cultists have withdrawn behind Mor Naril's walls.\n\nThey are counting on their soul flayers to defend them."] = "Hay sectarios del Gusano de bajo rango por todas partes, pero pocos líderes o puestos avanzados, aparte de la fortaleza Gristmung. Raz cree que la mayoría de los sectarios importantes se han retirado tras las murallas de Mor Naril.\n\nConfían en sus desolladores de almas para defenderlos.",
    ["For now, I'll rest. But it's likely Fenworine reported to some bigger Worm Cult nest. My plan is to meet Master Tanertor with an idea I had to bury them for good.\n\nAnd I'll do it with or without his help."] = "Por ahora, descansaré, pero es probable que Fenworine haya informado a algún nido del Culto del Gusano más grande. Quiero reunirme con el maestro Tanertor para hablarle de algo que se me ha ocurrido para enterrarlos para siempre.\n\nY lo haré con o sin su ayuda.",
    ["Tell me more about Velehk Sain."] = "Cuéntame más sobre tu tripulación. ¿Cómo acabasteis en Puerto Gélido?",
    ["Well, we're a long way from Alten Corimont, aren't we, pirate?\n\nAh, seems so long ago. Can't even remember the sounds and smells of the swamp. Sight's still burning with those endless waves of azure plasm. But it's good to be back in my home plane."] = "Bueno, estamos muy lejos de Alten Corimont, ¿verdad, pirata?\n\nAh, parece que ha pasado una eternidad. Ya ni siquiera recuerdo los sonidos y olores del pantano. En mi retina, siguen ardiendo esas interminables olas de plasma cerúleo, pero me alegra haber regresado a mi plano natal.",
    ["Hunt Down the Dakoi"] = "Da caza al Dakoi",
    ["There was. Celbrim. We were all with Master Rolmedil when the attack happened. He went to go help others after the portal didn't open. I chose to stay and protect Rolmedil, but ….\n\nI was just as scared, too."] = "Sí, Celbrim. Todos estábamos con el maestro Rolmedil cuando se produjo el ataque. Se fue a ayudar a otros cuando vio que el portal no se abría. Yo decidí quedarme para proteger a Rolmedil, pero...\n\nEstaba tan asustada como él.",
    ["You ask of things I was not taught as a death-dancer. I assume many of the voskrona around Mor Naril were damaged or destroyed in battle. I suspect any intact colossals are simply inert, having fulfilled their purpose long ago."] = "Preguntas cosas que no me enseñaron como bailarina de la muerte. Supongo que muchos de los voskrona acabaron dañados o destruidos en la batalla que se produjo alrededor de Mor Naril. Incluso sospecho que los colosos que sigan intactos estarán simplemente inertes, ya que cumplieron su propósito hace siglos.",
    ["You had no qualms about ending me. Prove to me that you can be just as ruthless toward this spy as you were toward me. Take the Eye to the room upstairs. No need to make a mess here.\n\nBring me proof when she's dead."] = "No tuviste reparos en matarme. Demuéstrame que puedes ser tan implacable con esta espía como lo fuiste conmigo. Lleva a la ojo a la sala que hay en el piso superior. No hace falta ensuciar este lugar.\n\nY trae una prueba de su muerte.",
    ["Thank you. I'm certain he would rather fling himself into the forge than open up to one of us. I'll try and mend things with Alma. We should've listened to her like you did."] = "Gracias. Seguro que prefiere tirarse de cabeza a la forja antes que contarnos lo que le pasa. Intentaré arreglar las cosas con Alma. Deberíamos haberla escuchado como tú.",
    ["Track the Dakoi"] = "Rastrea al Dakoi",
    ["Confront the Dakoi"] = "Enfréntate al Dakoi",
    ["Return to Yesei"] = "Vuelve con Yesei",
    ["Assist in Sculpting the Mudman"] = "Ayuda a esculpir el Hombre de Barro",
    ["Gather Mud"] = "Recoge barro",
    ["Return to Dailonda"] = "Vuelve con Dailonda",
    ["Smear Mud on the Mudman"] = "Embadurna al Hombre de Barro con barro",
    ["Prove Your Strength"] = "Demuestra tu fuerza",
    ["Take Hammer"] = "Toma el martillo",
    ["Return to Mahagog"] = "Vuelve con Mahagog",
    ["Break the Boulder"] = "Rompe el peñasco",
    ["Gather Honeycomb for Garth"] = "Recoge un panal para Garth",
    ["Gather Honeycomb"] = "Recoge un panal",
    ["Return to Garth"] = "Vuelve con Garth",
    ["Place the Honeycomb on the Feeding Stone"] = "Pon el panal en la piedra de alimentación",
    ["Perform the Ritual of Anseilak"] = "Realiza el ritual del Anseilak",
    ["Gather Seawater"] = "Recoge agua marina",
    ["Travel to Motalion Necropolis"] = "Viaja a la necrópolis de Motalion",
    ["Complete the Ritual of Anseilak"] = "Completa el ritual del Anseilak",
    ["You didn't know. I suspect the Dark Elf was clueless, too. Ormard was a vampire imprisoned here. Before we fell, that is.\n\nBlind wandering won't help save the mortal. Go south, look for other brightly lit rooms. You'll find a map on the wall in one."] = "No lo sabías. Y sospecho que el elfo oscuro tampoco tenía ni idea. Ormard es un vampiro que estaba aquí encerrado. Antes de que cayéramos, claro.\n\nVagando a ciegas, no conseguirás salvar al mortal. Ve al sur y busca otras salas muy iluminadas. En la pared de una de ellas, encontrarás un mapa.",
    ["We can hope. Though my suspicions grow the deeper we get inside this prison. Who left these Aspects around for us to easily find? And why was Terinvel so eager to rush in without me?\n\nAnd finally, why am I friends with such an inconsiderate person?"] = "Esperemos que sí, aunque mis sospechas van en aumento a medida que nos adentramos en esta prisión. ¿Quién dejó estos aspectos a la vista para que los encontráramos tan fácilmente? ¿Y por qué Terinvel tenía tantas ganas de entrar sin mí?\n\n¿Y por qué soy amiga de una persona tan desconsiderada?",
    ["I'll answer any questions, if you spare a potion or spell to aid me. \n\nYes, Ormard and a Dark Elf came through here. They did not notice me. They left in the direction of the courtyard."] = "Responderé a vuestras preguntas si me ayudáis con una poción o un hechizo.\n\nSí, Ormard y un elfo oscuro pasaron por aquí. No se fijaron en mí. Se dirigían al patio.",
    ["Thank you, stranger. I just want to leave this place. \n\nI had a family once, outside. I want to tell them what happened to me, if they're still alive."] = "Gracias, <<player{forastero/forastera}>>. Solo quiero salir de aquí.\n\nTenía familia, fuera. Quiero contarle lo que me ha pasado, si es que queda alguien con vida.",
    ["Talk to the Lone Traveler"] = "Habla con el viajero solitario",
    ["Fair warning—take even a sip and this partnership ends here and now. Bloodmite doesn't drink my blood, but he can find me just by taking a whiff of it. \n\nStrangely, it even helps relax him when he gets anxious."] = "El que avisa no es traidor: si bebes aunque solo sea un sorbito, esta asociación termina aquí y ahora. Ácaro de Sangre no bebe mi sangre, pero le basta olerla para encontrarme.\n\nPor extraño que parezca, incluso lo ayuda a relajarse cuando se pone nervioso.",
    ["Talk to the Hermit"] = "Habla con el ermitaño",
    ["I don't know. Such new feelings. Urges to dominate. Perhaps I'll take control of the University. Make all those pitiful academics praise me.\n\nYou should talk to Sirilonwe. I feel powerful thirst coming on."] = "No lo sé. Son sensaciones nuevas... Ansias de dominación. Quizá me apodere de la universidad y haga que todos esos académicos ridículos me rindan pleitesía.\n\nDeberías hablar con Sirilonwe. Siento que se avecina una sed intensa.",
    ["Heh. Been around my crew so long I forgot it might unsettle folk.\n\nIt's a curse. One I took to save the souls of the Lost Fleet, press-ganged past death to serve in Coldharbour. Now, it's just who I am. No thought of changing back."] = "Je. Llevo tanto tiempo con mi tripulación que había olvidado que esto podía perturbar a la gente.\n\nEs una maldición. Una que acepté para salvar las almas de la Flota Perdida, reclutadas más allá de la muerte para servir en Puerto Gélido. Ahora soy así. Y no quiero cambiar.",
    ["Dosu and I disagree on everything. Always have. But recently, we found something we agree on. Our feelings for one another.\n\nBut in how to consecrate this bond, we clearly disagree. Which courting custom would you find more meaningful, mainlander?"] = "Dosu y yo no nos ponemos de acuerdo en nada. Siempre ha sido así, pero últimamente, hemos encontrado algo en que coincidimos: nuestros sentimientos.\n\nEn cambio, diferimos radicalmente en cómo deseamos consagrar esta unión. ¿Qué costumbre de compromiso consideras más significativa, continental?",
    ["Well, yes … it all happened so fast! With her dying breath, brave Golvyni threw herself back into the fray to save me. I … I am not worthy of such a noble deed … but I shall try to be."] = "Bueno, sí... ¡Ocurrió todo tan rápido! La valiente Golvyni se lanzó a la reyerta con su último aliento para salvarme. Yo... no soy digno de un acto tan noble..., pero trataré de serlo a partir de ahora.",
    ["How long have you and Golvyni worked together?"] = "¿Cuánto tiempo llevabais colaborando Golvyni y tú?",
    ["Oh, where has this day gone? Speaking of my business, I really must be getting back to it now.\n\nFriend, Golvyni is at peace, you have your gold. Let it go. I have bear-lizards to skin and an ailing mother to visit."] = "Ay, se me ha pasado el día volando. Hablando de negocios, me temo que debo volver a los míos inmediatamente.\n\n<<player{Amigo/Amiga}>>, Golvyni está en paz y tú te has embolsado el oro. Déjalo estar. Tengo osos lagarto que desollar y una madre enferma que visitar.",
    ["I was inspired enough by Dullard and his crew to write an epic poem based on their adventures.\n\nWhile doing a reading just now, he felt the need to interrupt and take issues with my creative liberties regarding his selection of bedfellows."] = "Dullard y su tripulación me inspiraron lo suficiente como para escribir un poema épico basado en sus aventuras.\n\nHace un momento, mientras lo leía, Dullard ha sentido la necesidad de interrumpirme y discutir mis libertades creativas referentes a su selección de compañeros de cama.",
    ["The words of the dead? Really? You're going to believe scribbles in a journal instead of a hunter with an impeccable reputation? No, I fail to see how I deceived you. I only asked for help.\n\nBut you just wanted to be difficult …."] = "¿Las palabras de una muerta? ¿En serio? ¿Vas a creerte los garabatos de un diario en lugar del testimonio de un cazador con una reputación intachable? No, no consigo ver cómo te engañé. Solo te pedí ayuda.\n\nPero te empeñaste en complicar las cosas...",
    ["Gather Bait"] = "Recoge cebo",
    ["Are you afraid? Don't be. The cowardly are better to us dead than alive, and I will not hesitate to add your life to our power. \n\nSteel yourself. Soon, we rid this fortress of Naemon's presence!"] = "¿Tienes miedo? No deberías. Los cobardes nos son más útiles muertos que vivos y no dudaremos en alimentar nuestro poder con tu vida.\n\nÁrmate de coraje. ¡Pronto eliminaremos la presencia de Naemon en esta fortaleza!",
    ["Just one, but it requires a favor. I know, you've done plenty already. But could you find a way in, fix the platforms, maybe dispel a few wards? Meridia does love her magic traps! Then we can head inside.\n\nEasy stuff. You got this, right?"] = "Solo una, pero requiere un favor. Sí, sé que ya has hecho mucho por mí, pero ¿podrías averiguar cómo entrar, reparar las plataformas y, quizá, eliminar unas cuantas custodias? ¡A Meridia le encantan las trampas mágicas! Después, podremos entrar.\n\nEs pan comido. Te ves capaz, ¿no?",
    ["You were there? Perhaps you met Er-Jaseen. Crown and beard of black spines. Swishing tail. A kindness in his eyes."] = "¿Estuviste allí? Quizá conocieras a Er-Jaseen: cabeza y barba llenas de espinas negras, no paraba de menear la cola, su mirada desprendía bondad...",
    ["Er-Jaseen. He helped Argie escape the Wailing Prison. I meant for him to escape with me, but he stayed behind to help the others. \n\nThere were so many others. I don't know if he escaped. I should never have let him stay behind."] = "Er-Jaseen. Ayudó a Argie a escapar de la Prisión de los Lamentos. Quise que se fugase conmigo, pero se quedó atrás para ayudar al resto.\n\nHabía muchísima gente. No sé si logró huir. No debí permitirle que se quedara.",
    ["Walked right into that one, didn't I?\n\nIf only Salvus was here. You'd have him in stitches. No mirrors on the Spriggan. Heh."] = "Me lo he ganado a pulso, ¿verdad?\n\nOjalá estuviera aquí Salvo. Se partiría de risa. No hay espejos en el Spriggan. Je.",
    ["Find the Oblivion Boulder"] = "Encuentra el peñasco de Oblivion",
    ["The wraithforge was banished, torn from the very rock in the heart of Mor Naril. Some say the voskrona destroyed it. Others say Molag Bal took it into his realm to preserve it. No one remembers the exact details now."] = "La Forja Espectral fue desterrada, arrancada de la mismísima roca en el corazón de Mor Naril. Hay quienes afirman que los voskrona la destruyeron. Otros creen que Molag Bal se la llevó a su reino para preservarla. Ahora nadie recuerda los detalles con exactitud.",
    ["Without a single one of our crew seeing you? Hmm. Maybe you are the right sort to take out that observer.\n\nTry not to disappoint me, all right?"] = "¿Sin que nadie de nuestra tripulación te viera? Mmm. Puede que seas la persona adecuada para eliminar a ese observador.\n\nIntenta no decepcionarme, ¿vale?",
    ["Remember Camlorn. Your dad. Alinon. The people there."] = "Recuerda Camlorn. A tu padre. A Alinon. A las personas de allí.",
    ["Remember Shornhelm. Sneaking into Northpoint. Your … antics."] = "Recuerda Timón Despojado. Cómo nos colamos en Punta Norte. Tus... travesuras.",
    ["Remember Coldharbour. How we fought alongside King Dynar. How we stopped Molag Bal."] = "Recuerda Puerto Gélido. Cómo luchamos junto al rey Dynar. Cómo detuvimos a Molag Bal.",
    ["I have gone to great lengths to define my authority and the boundaries of the prince's. No one will confuse them again.\n\nIf there are any issues, come to me or one of my aides. We will be more than pleased to clarify who is in charge here."] = "He hecho grandes esfuerzos por definir mi autoridad y los límites de la del príncipe. Nadie volverá a confundirlas.\n\nSi surgen problemas, acude a mí o a cualquiera de mis asistentes. Será un placer aclarar quién está al mando aquí.",
    ["I am, of course, limited by the bargains I strike with prevailing Princes, but yes. I am a Daedra with many forms. But I do not use this gift to seek power.\n\nOnce I have experienced all Oblivion has to offer, I will finally know who I am."] = "Obviamente, existen limitaciones respecto a los tratos que puedo acordar con los príncipes reinantes, pero sí. Aunque soy une daedra con muchas formas, no utilizo este don para lograr poder.\n\nEn cuanto haya experimentado todo lo que Oblivion tiene que ofrecer, sabré finalmente quién soy.",
    ["I can spare a few moments before I resume my preparations to return to the mainland. You've more than earned the right to ask questions, champion."] = "Puedo dedicarte unos momentos antes de proseguir con mis preparativos para regresar al continente. Te has ganado con creces el derecho a formular preguntas, <<player{campeón/campeona}>>.",
    ["Why would Molag Bal make vampires fight each other?"] = "¿Por qué querría Molag Bal que los vampiros se peleasen?",
    ["Looking for inspiration! I heard all about the goings-on here and I tried to get here as fast as I could.\n\nSeems like most of the good stuff happened without me here to witness. I'm trying to get what information I can so the trip isn't a total loss."] = "¡Buscar inspiración! Me enteré de todo lo que estaba pasando aquí y vine lo antes posible.\n\nAunque parece que me he perdido lo mejor. Estoy intentando recopilar información para que el viaje no haya sido completamente en balde.",
    ["As vampires age, they gain strength. Physically and magically. And coming here breaks your morality after a while. The kind don't grow old.\n\nElder prisoners force the young to protect them. At threat of exsanguination."] = "Conforme envejecen, los vampiros se vuelven más fuertes; a nivel físico y mágico. Además, después de pasar un tiempo aquí, tu sentido de la moralidad acaba desapareciendo. Los vampiros amables no llegan a viejos.\n\nLos prisioneros ancianos obligan a los jóvenes a protegerlos; bajo amenaza de desangramiento.",
    ["As good as I can be after whatever that was in the temple. Did Vanus fill you in? I tried to avoid him, but he's surprisingly limber for a centuries old mage.\n\nBut we're not here to talk about Vanus. Unless you … want to talk about Vanus?"] = "Lo mejor que puedo estar después de lo que pasó en el templo. ¿Te lo ha contado Vano? Intenté que no me siguiera, pero está sorprendentemente ágil para ser un mago con varios cientos de años.\n\nAunque no estamos aquí para hablar de Vano. A menos que... quieras hablar de Vano. ¿Es eso?",
    ["Observe Sirilonwe's Magic"] = "Observa la magia de Sirilonwe",
    ["Search the Broken Walkway"] = "Registra la Pasarela Quebrada",
    ["Perform a Dance in the Mud"] = "Baila en el barro",
    ["Use any Musical Emote"] = "Usa cualquier gesto musical",
    ["Player Died"] = "Jugador muerto",
    ["Player Logged Out"] = "Jugador desconectado",
    ["Notes written by Vanus Galerion to Gabrielle and smuggled out of his prison by Baar-Jasa."] = "Notas que Vano Galerion escribió a Gabrielle y Baar-Jasa sacó a escondidas de su prisión.",
    ["Not precisely, but they know to head to the portal gates in emergencies. However, they need a keystone to activate them and return to Sunport.\n\nTake my keystone. Activate the portals and save my apprentices. I promise to reward you for your efforts."] = "No con precisión, pero saben que deben dirigirse a las entradas de portal en caso de emergencia. Sin embargo, necesitan una piedra angular para activarlas y regresar a Puerto Soleado.\n\nToma mi piedra angular, activa los portales y salva a mis aprendices. Te prometo que te compensaré por tus esfuerzos.",
    ["Captain One-Eye. She'll know what to do. Help us, and I'll make sure she cuts you in for a share of our plunder.\n\nThe ships came down by those cliffs to the north. I think, if the captain made it, that is where she'll rally the crew."] = "La capitana Ojo Único. Ella sabrá qué hacer. Ayúdanos y me aseguraré de que te dé una parte de nuestro botín.\n\nLos barcos descendieron por esos acantilados que hay al norte. Si la capitana ha sobrevivido, creo que es allí donde reunirá a la tripulación.",
    ["You can't find anyone to help you out?"] = "¿No encuentras a nadie que te ayude?",
    ["I'll help. What exactly do you need me to do?"] = "Yo te ayudaré. ¿Qué necesitas que haga exactamente?",
    ["You made all this food for someone else?"] = "¿Has preparado toda esta comida para alguien más?",
    ["A lot of someones, actually. It's an offering for elders in our community. A chance to pay them back for years of wisdom this New Life, but I'm struggling to find anyone to help me with the final preparations."] = "Para muchos «álguienes» más. Es una ofrenda para los ancianos de la comunidad, para agradecerles sus años de sabiduría esta Nueva Vida, pero me está costando encontrar ayuda con los preparativos finales.",
    ["Everyone's busy with something, from the Three Banners War to a knotted ball of their own problems. And some simply don't care.\n\nSince you seem even the least bit interested, would you be willing to help me? For New Life, and for pay, of course."] = "Todo el mundo está ocupado con algo, ya sea la Guerra de los Tres Estandartes o sus propios problemas. A algunas personas, simplemente no les importa.\n\nYa que has mostrado cierto interés, ¿querrías ayudarme? Por la Nueva Vida, y por una recompensa, claro.",
    ["A little help for New Life would be appreciated …."] = "Un poco de ayuda por la Nueva Vida sería bienvenida...",
    ["A coin swiped from the hoard of Rawl'kha's Dragon as part of the New Life Festival."] = "Una moneda birlada del tesoro del dragón de Rawl'kha durante la celebración del Festival de la Nueva Vida.",
    ["Dragon's Coin"] = "moneda del dragón^f",
    ["Tricky in what way?"] = "¿Complicado? ¿En qué sentido?",
    ["All right. Where can I find the Dragon?"] = "Muy bien. ¿Dónde puedo encontrar al dragón?",
    ["Rawl'kha's Dragon?"] = "¿El dragón de Rawl'kha?",
    ["Tibarr apologizes. This one did not mean to alarm. We are in no danger. It is our New Life tradition to steal the Dragon's treasure and distribute it to the needy. Tibarr always organizes it!\n\nHowever, this season's challenge has been … tricky."] = "Tibarr te pide perdón. Este khajiita no pretendía alarmarte. No corremos peligro. En la Nueva Vida, tenemos la tradición de robar el tesoro de un dragón y repartirlo entre los necesitados. ¡Tibarr siempre se encarga de organizarlo!\n\nSin embargo, esta estación el desafío ha sido... complicado.",
    ["Now, that would spoil the fun! This New Life tradition seeks to help us sharpen both our minds and our claws. Will you try to abscond with the Dragon's hoard?\n\nTibarr promises a portion of the gold will be yours to keep!"] = "¡Ah, eso chafaría la diversión! El objetivo de esta tradición de la Nueva Vida es ayudarnos a aguzar el ingenio y las garras. ¿Quieres probar a sustraer el tesoro del dragón?\n\n¡Tibarr promete darte parte del oro!",
    ["Who will face Rawl'kha's Dragon for New Life?"] = "¿Quién se enfrentará al dragón de Rawl'kha por la Nueva Vida?",
    ["Fresh mud collected for Dailonda's Mudman."] = "Barro fresco recogido para el Hombre de Barro de Dailonda.",
    ["Mudman Mud"] = "barro para el Hombre de Barro^m",
    ["What's making it so difficult?"] = "¿Por qué resulta tan difícil?",
    ["All right. Where can I find the Dakoi?"] = "Muy bien. ¿Dónde puedo encontrar al Dakoi?",
    ["Who's Dakoi?"] = "¿Quién es Dakoi?",
    ["Not a who. A what! Dakoi is a very special, sly … fish. Every New Life season, it greets our waters. It's said good fortune and growth comes to those who feast on this particular fish.\n\nBut, lately, it's proving difficult to catch."] = "La pregunta correcta no es «quién», ¡sino «qué»! El Dakoi es un... pez muy especial y astuto. Llega a nuestras aguas con cada Nueva Vida. Dicen que quienes comen este pez disfrutan de buena fortuna y crecimiento.\n\nPero últimamente resulta difícil pescarlo.",
    ["The fish has more tricks than a New Life Festival performer! I promised to reel it in for tonight's feast, but the Dakoi …. I refuse to be embarrassed any further!\n\nHunt the Dakoi for me, and I guarantee you'll get more than just good fortune."] = "¡Ese pez se sabe más trucos que un artista del Festival de la Nueva Vida! Prometí atraparlo para el banquete de esta noche, pero el Dakoi... ¡Me niego a seguir pasando vergüenza!\n\nAtrapa el Dakoi por mí y te aseguro que obtendrás algo más que buena fortuna.",
    ["That clever little Dakoi can't elude me forever."] = "Ese Dakoi listillo no puede esquivarme para siempre.",
    ["Forged by Orsimer Orcs to break boulders for Betnikh's Boon in the New Life Festival."] = "Forjado por orcos para romper peñascos y conseguir la bendición de Betnikh en el Festival de la Nueva Vida.",
    ["Where are your kin?"] = "¿Dónde está tu familia?",
    ["All right. What kind of mud do you need?"] = "Vale. ¿Qué tipo de barro necesitas?",
    ["What kind of blessing?"] = "¿Qué tipo de bendición?",
    ["One only available during New Life. The Mudman is an effigy my kin and I construct to bless the new year with fertile growth across all of Tamriel.\n\nAnd … now I must do it without them."] = "Una que solo está disponible durante la Nueva Vida. El Hombre de Barro es una efigie que construimos para que el nuevo año traiga abundancia a todo Tamriel.\n\nY... ahora debo hacerlo sin mi familia.",
    ["Gone to spread their roots beyond Grahtwood. My home is here with my followers, but with our numbers reduced, we struggle to complete the Mudman.\n\nI believe your path through the Green has led you here. Help us gather mud and you'll be rewarded."] = "Mis retoños decidieron extender sus raíces más allá del Bosque Graht. Mi hogar está aquí, con mis seguidores, pero como somos pocos, nos está costando terminar el Hombre de Barro.\n\nCreo que tu camino a través del Verde te ha traído aquí. Ayúdanos a recoger barro y te recompensaremos.",
    ["Let our prayers bring the Mudman to life!"] = "¡Que nuestras plegarias le insuflen vida al Hombre de Barro!",
    ["A sweet and succulent honeycomb. Surely this will lighten the mood of the hermit's bear, Garth."] = "Un panal dulce y suculento. Seguro que esto mejorará el humor de Garth, el oso del ermitaño.",
    ["Succulent Honeycomb"] = "panal suculento^m",
    ["You want me to smash a boulder?"] = "¿Quieres que machaque un peñasco?",
    ["I accept your challenge. What kind of boulder do you have in mind?"] = "Acepto el desafío. ¿Qué clase de peñasco tienes en mente?",
    ["What sort of competition?"] = "¿Qué tipo de competición?",
    ["Just the best New Life has to offer! We haul in big boulders and smash them. Whoever breaks a boulder into the smallest bits with one strike claims a boon of good health until the next New Life.\n\nAnd with bragging rights, of course."] = "¡Lo mejor que puede ofrecer la Nueva Vida! Traemos grandes peñascos y los machacamos. Quien consigue partir un peñasco en los trozos más pequeños de un solo golpe goza de buena salud hasta la siguiente Nueva Vida.\n\nY tiene todo el derecho a alardear, por supuesto.",
    ["Not just any boulder! Let's make it interesting and find one that's truly worthy of Betnikh's Boon! Something none of these losers could ever hope to chip or crack. I'll even throw in something extra for the winner. \n\nSo, friend, what do you say?"] = "Pero ¡no cualquier peñasco! ¡Para que sea más interesante, hay que buscar uno que sea digno de la bendición de Betnikh! Uno que estos incompetentes no podrían aspirar siquiera a astillar ni resquebrajar. Y el ganador se llevará algún extra.\n\nBueno, <<player{amigo/amiga}>>, ¿qué me dices?",
    ["Can no one provide a proper challenge this New Life?"] = "¿Nadie puede plantearme un desafío de verdad esta Nueva Vida?",
    ["Why is Garth in a bad mood?"] = "¿Por qué está de mal humor Garth?",
    ["All right. Where can I find some honeycomb?"] = "Muy bien. ¿Dónde puedo encontrar un panal de miel?",
    ["Garth wants to eat Tamriel?"] = "¿Garth quiere comerse Tamriel?",
    ["Eat, destroy, same difference. The Skaals in the village don't believe it, but Garth has a piece of the All-Maker in him. And it's his jolly mood during New Life that determines Tamriel's fate for the coming year!\n\nRight now, it's not looking good."] = "Comer, destruir, ¿qué más da? Los skaal de la aldea no me creen, pero Garth tiene una parte del Creador en su interior, ¡y su alegría durante la Nueva Vida determina el destino de Tamriel durante el año venidero!\n\nAhora mismo, no pinta nada bien.",
    ["Ask the fool in his belly the next time you meet him. At least he was calm while I juggled and … wait.\n\nHoneycomb! That will brighten Garth's mood! Bring him some while I keep juggling and we may just save Tamriel and New Life yet!"] = "Pregúntaselo al idiota que tiene en la panza la próxima vez que lo veas. Al menos, estuvo tranquilo durante mis juegos malabares... ¡Espera!\n\n¡Un panal! ¡Eso lo alegrará! ¡Tráele un panal a Garth mientras sigo haciendo malabares! ¡Tal vez salvemos la Nueva Vida y a Tamriel!",
    ["What's wrong, Garth? My juggling used to soothe you."] = "¿Qué te pasa, Garth? Antes te calmabas con mis malabares.",
    ["Despite its seemingly ancient make, this water skin shows no signs of wear and tear."] = "Este odre de agua, de factura aparentemente antigua, no muestra señas de desgaste.",
    ["What is Anseilak, and how do I give them that?"] = "¿Qué es el Anseilak y cómo se lo ofrezco?",
    ["All right. I'll help you perform Anseilak for the Yokudan mages."] = "De acuerdo. Te ayudaré a celebrar el Anseilak para los magos yokudanos.",
    ["No. What're you on pilgrimage for?"] = "No. ¿Por qué estás de peregrinaje?",
    ["Withered Water Skin"] = "odre avejentado^m",
    ["If only I could survive the journey. Every New Life, we give Anseilak to the fallen Yokudans so that their spirits may rest peacefully. However, Yokudan mages are ignored for their involvement in magic.\n\nTraveler. Will you give them Anseilak?"] = "Ojalá pudiera sobrevivir al viaje. Cada Nueva Vida, ofrecemos el Anseilak a los yokudanos caídos para que sus espíritus descansen en paz. Sin embargo, se ignora a los magos yokudanos debido a su conexión con la magia.\n\n<<player{Viajero/Viajera}>>, ¿aceptarías ofrecerles el Anseilak?",
    ["Forgive me. It is a ritual where we gather seawater that once touched Yokuda's lands. We then perform it for the fallen mages resting at Motalion Necropolis, bringing them peace.\n\nKnow your efforts will be repaid in full."] = "Perdona, se trata de un ritual en que reunimos agua marina que ha bañado las tierras yokudanas. A continuación, lo celebramos por los magos caídos que reposan en la necrópolis de Motalion, para darles descanso.\n\nTus esfuerzos serán bien recompensados.",
    ["I must bring peace to the rest of the Yokudans."] = "Debo dar descanso al resto de los yokudanos.",
    ["Water that once touched the ancient land of Yokuda, now sunken deep beneath the sea."] = "Agua que en su día bañó las antiguas tierras yokudanas, ahora hundidas en las profundidades del mar.",
    ["Fresh Seawater"] = "agua marina fresca^fm",
    ["You prepared a hearty, rich baked potato for Nenilon. Deliver it to him near the banks of Toothmaul Gully as an offering for New Life."] = "Has preparado una patata asada contundente y sabrosa para Nenilon. Entrégasela cerca de las laderas de la Quebrada Diente Roto como ofrenda por la Nueva Vida.",
    ["I learned that Lanullin is leading an effort to give back to esteemed High Elf elders in her community. However, it seems they're shorthanded. I agreed to help her however I can."] = "He descubierto que Lanullin lidera una iniciativa para corresponder a los ancianos de su comunidad que más aprecia. Sin embargo, parece que no da abasto. He aceptado ayudarla como esté en mi mano.",
    ["Giving back? How?"] = "¿Corresponder? ¿Cómo?",
    ["All right. I'll help Lanullin in Auridon."] = "De acuerdo, ayudaré a Lanullin en Auridon.",
    ["I'm interested. Tell me more."] = "Suena interesante. Cuéntame más.",
    ["Nenilon's Baked Potato Offering"] = "ofrenda de patata asada para Nenilon^f",
    ["Here's a New Life festivity that strikes a chord in me. Lanullin leads an earnest effort to give back to High Elf elders this season, especially those who shared their wisdom with her community."] = "Se trata de un festejo de la Nueva Vida que me toca la fibra. Lanullin está liderando una iniciativa honorable para corresponder a los ancianos altmeri durante la celebración, sobre todo a aquellos que compartieron su sabiduría con la comunidad.",
    ["By rattling pots and pans and cooking up something delicious! A shame, though. I hear she doesn't have enough help to make offerings for all the elders she hopes to provide for.\n\nCould you lend them a hand in Auridon, friend?"] = "¡Meneando ollas y sartenes, y preparando algo delicioso! Aunque es una lástima... He oído que no cuenta con ayuda suficiente para preparar las ofrendas de todos los ancianos a los que le gustaría atender.\n\n¿Podrías echarle una mano en Auridon, <<player{amigo/amiga}>>?",
    ["Help support Auridon's elders for New Life!"] = "¡Ayudad a apoyar a los ancianos de Auridon por la Nueva Vida!",
    ["You prepared a sweet and tempting banana surprise for Geraldrim. Deliver it to him near the Ezduiin's Ruins as an offering for New Life."] = "Has preparado una sorpresa bananera dulce y apetecible para Geraldrim. Entrégasela cerca de las ruinas de Ezduiin como ofrenda por la Nueva Vida.",
    ["A wealthy Khajiit seems to be hosting a game for New Life that involves hoards of gold and a grand opponent guarding it. To learn more, I need to speak to Tibarr, the organizer for this festivity."] = "Parece que un khajiita adinerado organiza un juego por la Nueva Vida que incluye un botín de oro y un gran oponente que lo custodia. Si quiero informarme más, tengo que hablar con Tibarr, el organizador del festejo.",
    ["Tell me about this guardian."] = "Háblame de ese guardián.",
    ["All right. I'll speak to Tibarr in Rawl'kha."] = "De acuerdo. Hablaré con Tibarr en Rawl'kha.",
    ["Geraldrim's Banana Surprise Offering"] = "ofrenda de sorpresa bananera para Geraldrim^f",
    ["I hesitate to mention due to the danger, but you seem the daring sort. A wealthy Khajiit in Rawl'kha has put a hoard of gold on the line—if you can overcome its guardian."] = "Me resisto a comentártelo por el peligro que entraña, pero pareces <<player{un tipo osado/una tipa osada}>>. Un khajiita adinerado de Rawl'kha ha puesto en juego un botín de oro. Podrás conseguirlo si superas a su guardián.",
    ["New Life is about surprises, too, my friend! I'll let Tibarr be the one to reveal his grand scheme to you.\n\nBut a word of caution—watch your step when you face the guardian!"] = "¡La Nueva Vida también incluye sorpresas, <<player{amigo mío/amiga mía}>>! Dejaré que sea Tibarr quien te revele su ambicioso plan.\n\nPero debo hacerte una advertencia: ¡ve con cuidado cuando te enfrentes al guardián!",
    ["Here's a New Life festivity for those who love a challenge!"] = "¡He aquí un festejo de la Nueva Vida para amantes de los desafíos!",
    ["You prepared a warm, nourishing carrot soup for Teliwe. Deliver it to her at the College of Aldmeri as an offering for New Life."] = "Has preparado una sopa de zanahoria caliente y nutritiva para Teliwe. Entrégasela en el Colegio del Decoro Aldmeri como ofrenda por la Nueva Vida.",
    ["Anicus mentioned an angler called Yesei trying to catch a fabled Dakoi fish for New Life. He thinks he needs help, and that I should speak to him."] = "Anico ha mencionado a un pescador llamado Yesei que está intentando atrapar a un pez Dakoi mítico por la Nueva Vida. Cree que necesita ayuda y que debería hablar con él.",
    ["Interesting. Tell me more."] = "Qué interesante. Cuéntame más.",
    ["All right. I'll find Yesei in Stormhold."] = "De acuerdo. Buscaré a Yesei en Fuerte de la Tormenta.",
    ["Teliwe's Carrot Soup Offering"] = "ofrenda de sopa de zanahoria para Teliwe^f",
    ["Let me tell you about the murky waters of Stormhold. Nearly fell in when a poor angler rushed past me in pursuit of the fabled Dakoi fish.\n\nIt's a strange way to celebrate New Life, but that's what makes it special!"] = "Déjame hablarte sobre las aguas turbias de Fuerte de la Tormenta. Casi me caigo en ellas cuando un pobre pescador me adelantó en plena persecución del mítico pez Dakoi.\n\nEs una forma extraña de celebrar la Nueva Vida, pero ¡por eso es especial!",
    ["The Dakoi only appears during the New Life season. Poor Yesei has been chasing it all over Stormhold. Whoever catches it gets a year of good luck, and Yesei could really use some.\n\nIf you don't mind getting a little wet, go help him out!"] = "El Dakoi solo aparece durante la celebración de la Nueva Vida. El pobre Yesei ha estado persiguiéndolo por todo Fuerte de la Tormenta. Quien lo atrape tendrá un año de buena suerte, y a Yesei no le vendría nada mal.\n\nSi no te importa mojarte un poco, ¡ve a echarle una mano!",
    ["Will you be the one to hook Stormhold's fabled Dakoi this season?"] = "¿Serás tú quien le eche el anzuelo al mítico Dakoi de Fuerte de la Tormenta esta estación?",
    ["Prepare carrot soup and deliver it to Teliwe at the College of Aldmeri as an offering for New Life."] = "Prepara una sopa de zanahoria y entrégasela a Teliwe en el Colegio del Decoro Aldmeri como ofrenda por la Nueva Vida.",
    ["In Elden Root, Dailonda and her followers are constructing a Mudman effigy to bless Tamriel, but they need a hand. I agreed to help her however I can."] = "En Raíz de Elden, Dailonda y sus seguidores están construyendo una efigie del Hombre de Barro para bendecir Tamriel, pero necesitan ayuda. He accedido a echarles una mano.",
    ["Mudman effigy? She's sculpting with mud?"] = "¿Una efigie del Hombre de Barro? ¿Está esculpiendo con barro?",
    ["I'll head to Elden Root and help Dailonda."] = "Iré a Raíz de Elden y ayudaré a Dailonda.",
    ["This one's a bit messy. Dailonda's kin usually help her with the sculpting for New Life, but they all recently departed Elden Root's branches for newer trees.\n\nNow, it's only her, a few of her followers, and their Mudman effigy."] = "Esta es un tanto pringosa. Los familiares de Dailonda suelen ayudarla a esculpir por la Nueva Vida, pero han abandonado las ramas de Raíz de Elden recientemente para buscar nuevos árboles.\n\nAhora está sola con unos pocos seguidores y su efigie del Hombre de Barro.",
    ["Like I said, messy. When completed, the Mudman bestows its blessing upon Tamriel. But poor Dailonda also believes that bad luck follows if the sculpture isn't finished.\n\nSo, are you up for frolicking in the mud and lending a hand?"] = "Como he dicho, es un asunto pringoso. Cuando esté terminado, el Hombre de Barro concederá su bendición a Tamriel, pero la pobre Dailonda también cree que la escultura traerá mala suerte si no la terminan.\n\nBueno, ¿te animas a rebozarte en el barro y echarle una mano?",
    ["Who doesn't mind a little dirt for a New Life blessing?"] = "¿A quién no le importa mancharse un poco a cambio de una bendición de la Nueva Vida?",
    ["Prepare a baked potato and deliver it to Nenilon near the banks of Toothmaul Gully as an offering for New Life."] = "Prepara una patata asada y entrégasela a Nenilon cerca de las laderas de la Quebrada Diente Roto como ofrenda por la Nueva Vida.",
    ["I learned that a group of Orcs in Betnikh celebrate New Life by breaking boulders for a special boon. To participate, I need to speak to Mahagog, their leader."] = "He descubierto que un grupo de orcos de Betnikh celebra la Nueva Vida rompiendo peñascos para conseguir una bendición especial. Si quiero participar, tengo que hablar con Mahagog, su líder.",
    ["What's Betnikh's Boon?"] = "¿Qué es la bendición de Betnikh?",
    ["All right. I'll talk to Mahagog at Stonetooth Fortress."] = "De acuerdo, hablaré con Mahagog en la fortaleza de Diente de Piedra.",
    ["Orcs over in Betnikh compete for Betnikh's Boon in a contest of strength every New Life. The competition involves physical strength, keen reflexes, and huge boulders!"] = "Los orcos de Betnikh compiten entre sí por la bendición de Betnikh en un concurso de fuerza cada Nueva Vida. La competición exige tener fuerza física, reflejos ágiles ¡y peñascos enormes!",
    ["A favor or benefit of some kind. You'd have to ask Mahagog. He's leading the contest. You can find him at Stonetooth Fortress in Betnikh.\n\nFair warning—he loves competition and hates to lose."] = "Un favor o ventaja de algún tipo. Tendrás que preguntárselo a Mahagog, que es quien organiza el concurso. Lo encontrarás en la fortaleza de Diente de Piedra, en Betnikh.\n\nSolo una advertencia: le encanta competir, pero odia perder.",
    ["If you've got muscles, I've got a New Life festivity for you!"] = "Si tienes buena musculatura, ¡tengo un festejo de la Nueva Vida para ti!",
    ["Prepare a banana surprise and deliver it to Geraldrim near the Ezduiin's Ruins as an offering for New Life."] = "Prepara una sorpresa bananera y entrégasela a Geraldrim cerca de las ruinas de Ezduiin como ofrenda por la Nueva Vida.",
    ["A lone traveler seems to be asking for help making a pilgrimage. Supposedly, it can help bring peace to the fallen Yokudans during New Life. I agreed to help however I can."] = "Alguien que viaja en solitario está pidiendo ayuda para su peregrinación. Por lo que dice, contribuirá a dar descanso a los yokudanos caídos durante la Nueva Vida. He accedido a ayudar como pueda.",
    ["Any reason why nobody wants to help them?"] = "¿Hay alguna razón por la que nadie quiera ayudar?",
    ["All right. I'll find them in Sentinel."] = "De acuerdo, buscaré a esa persona en Centinela.",
    ["This one I haven't been able to check personally. Whispers carried by Sentinel's winds tell of a lone traveler seeking help from passersby for New Life. Something about a pilgrimage to bring fallen Yokudans peace.\n\nAlas, the pleas fall on deaf ears."] = "Este khajiita no ha podido comprobarlo personalmente, pero los susurros que traen los vientos de Centinela hablan de alguien que viaja en solitario y busca ayuda de los transeúntes durante la Nueva Vida. Algo sobre una peregrinación para darles descanso a los yokudanos caídos.\n\nPor desgracia, sus súplicas caen en oídos sordos.",
    ["Who can say? I hear Redguard have peculiar notions regarding the dead, so perhaps that's part of it.\n\nIf you can deal with hot sand and biting winds, seek them out in Sentinel. It would be a shame if their approach to New Life didn't succeed."] = "¿Quién sabe? He oído que los Guardias Rojos tienen nociones peculiares sobre los muertos, así que tal vez sea por eso.\n\nSi puedes soportar la arena ardiente y los vientos cortantes, busca a esa persona en Centinela. Sería una pena que fracasase en su misión por la Nueva Vida.",
    ["New Life and long dead in Sentinel! Ask me for details!"] = "¡Nueva Vida y fallecidos antaño en Centinela! ¡Pregúntame por los detalles!",
    ["Many Nords seem to describe a hermit claiming that his pet bear's mood is important this New Life. I should speak to him to learn more about what he needs."] = "Muchos nórdicos hablan de un ermitaño que asegura que el humor del oso que tiene como mascota es importante esta Nueva Vida. Debería hablar con él para descubrir qué necesita.",
    ["His bear?"] = "¿Su oso?",
    ["All right. I'll head to the Rift and talk to the hermit."] = "De acuerdo, iré a La Grieta y hablaré con el ermitaño.",
    ["Here's a bizarre one I haven't had a chance to check on yet. A crazed hermit in the Rift proclaims this will be the last New Life. That the end of days are upon us. Heh, what else is new?\n\nBut here's the twist—his bear is the problem."] = "Esta historia es muy extraña y aún no he tenido tiempo de comprobarla personalmente. Un ermitaño loco de La Grieta afirma que el fin de los días está al caer y que esta será la última Nueva Vida. ¡Ja! ¿Acaso es una novedad?\n\nPero hay una sorpresita: dice que el problema es su oso.",
    ["Pet bear, yes. Seems like the bear's mood determines the fate of each New Life, and right now the bear is miserable. The hermit needs help cheering him up.\n\nThe bear's also … quite large. Hard to miss. Find them by a lake near Skald's Retreat."] = "Un oso que tiene como mascota, sí. Parece que el humor del oso determina el destino de cada Nueva Vida y, ahora mismo, el oso está muy triste. El ermitaño necesita ayuda para animarlo.\n\nAdemás, este oso es... bastante grande. Es difícil no verlo. Los encontrarás junto a un lago cerca del Retiro del Escaldo.",
    ["Hermit claims this may be Tamriel's last New Life! Talk to me to learn more!"] = "¡Un ermitaño afirma que esta podría ser la última Nueva Vida de Tamriel! ¡Habla conmigo y te contaré más!",
    ["An empty bottle of bloodwine that still has a strong scent to it."] = "Una botella de vino de sangre vacía que aún conserva un fuerte aroma.",
    ["I met Jahesi once again out in Sentinel. It seems she'd like to continue performing Anseilak for the fallen Yokudan mages until New Life's end. I agreed to travel with her and help with the ritual."] = "He vuelto a encontrarme con Jahesi en Centinela. Parece que le gustaría seguir realizando el Anseilak para los magos yokudanos caídos hasta que termine la Nueva Vida. He accedido a viajar con ella y ayudarla con el ritual.",
    ["And you're going to do this every day?"] = "¿Y piensas hacerlo cada día?",
    ["All right. Let's perform Anseilak."] = "Muy bien. Celebremos el Anseilak.",
    ["Do you need help with something?"] = "¿Necesitas ayuda con algo?",
    ["Bottle of Bloodwine"] = "botella de vino de sangre^f",
    ["I need to perform Anseilak for the other Yokudan mages, but my blessing alone won't be enough to make up for the centuries they've been shunned. And most Redguard scowl when I mention them."] = "Tengo que llevar a cabo el Anseilak para los demás magos yokudanos, pero mi bendición no basta por sí sola para compensar los siglos que han estado marginados. Y la mayoría de los Guardias Rojos fruncen el ceño al mencionárselo.",
    ["Until New Life's end. You certainly don't have to trudge through the sand with me every day. But having another blessing would help the mages. And me.\n\nRest assured I'll reward you for your time."] = "Hasta que concluya la Nueva Vida. Ciertamente, no todos los días tendrás que caminar por la arena a duras penas conmigo, pero a los magos les vendría bien otra bendición. Y a mí también.\n\nTen por seguro que te recompensaré por tu tiempo.",
    ["Alik'r's winds have reunited us once more, traveler."] = "Los vientos de Alik'r han vuelto a reunirnos, <<player{viajero/viajera}>>.",
    ["A wet, earthy clump of mud. Caught and reeled from Shadowfen's fishing holes."] = "Un terrón de barro húmedo y terroso extraído de los lugares de pesca del Pantano de las Sombras.",
    ["Clump of Mud"] = "terrón de barro^m",
    ["Shriveled fish scales. Probably the leftovers of a predator's meal."] = "Unas escamas de pez resecas. Seguramente sean restos de la comida de algún depredador.",
    ["Bundle of Fish Scales"] = "montón de escamas de pez^m",
    ["I don't know what the Worm Cult wants with the Staff of Magnus or Prince Naemon, but it sounds disastrous. Queen Ayrenn, the Dominion, everything is in jeopardy.\n \nI have the beginnings of a plan, but I can't move fast enough with this injury."] = "No sé qué quiere hacer el Culto del Gusano con el Bastón de Magnus o el príncipe Naemon, pero podría ser desastroso. La reina Ayrenn, el Dominio..., todo está en peligro.\n\nEstoy esbozando un plan, pero no voy a poder actuar con suficiente rapidez por culpa de esta herida.",
    ["A Trick to the Doors"] = "Un truco para las puertas",
    ["What does it hurt to spin some yarn about me dying like a hero? I just want her to remember me with fondness, that's all.\n\nI'm sure she'll pay you for your delivering the news. She has a good heart. Please. Above all else, she needs to know."] = "¿Qué daño puede hacer un cuentecillo sobre cómo morí de forma heroica? Solo quiero que me recuerde con cariño, eso es todo.\n\nSeguro que te pagará por darle la noticia; tiene buen corazón. Por favor. Ante todo, necesita saberlo.",
    ["A carelessly dropped note written by Terinvel. Sirilonwe wants to see it."] = "Una nota que se le cayó a Terinvel en un descuido. Sirilonwe quiere verla.",
    ["Glenumbra"] = "Glenumbra^F",
}